import subprocess, time, os, tempfile, pathlib, sys
EXE=os.path.join(os.getcwd(),"executable")
def do_run(name, answers, args_extra=[], setup=None):
    td=tempfile.mkdtemp()
    print(f"\n=== {name} td={td} answers={answers} extra={args_extra} ===")
    if setup: setup(td)
    sess="gen_"+name
    subprocess.run(["tmux","kill-session","-t",sess], capture_output=True)
    cmd = f"{EXE} generate ci {' '.join(args_extra)}; echo EXIT:$?; sleep 100"
    subprocess.run(["tmux","new-session","-d","-s",sess,"-c",td, cmd])
    time.sleep(0.8)
    def cap():
        r=subprocess.run(["tmux","capture-pane","-t",sess,"-p"], capture_output=True, text=True)
        return r.stdout
    for a in answers:
        print("CAP before:", cap())
        if a=="Enter":
            subprocess.run(["tmux","send-keys","-t",sess,"Enter"])
        else:
            subprocess.run(["tmux","send-keys","-t",sess,a,"Enter"])
        time.sleep(0.8)
    print("FINAL CAP:", cap())
    for p in sorted(pathlib.Path(td).rglob("*")):
        print("FILE:",p.relative_to(td))
        if p.is_file():
            try: print(repr(p.read_text()))
            except Exception as e: print(e)
    subprocess.run(["tmux","kill-session","-t",sess], capture_output=True)

do_run("default", ["Enter","Enter","Enter"])
do_run("all_n", ["n","n","n"])
do_run("all_y", ["y","y","y"])
do_run("mixed", ["n","y","y"])
