import subprocess, os, tempfile, pathlib, time, socket, urllib.request, urllib.error
EXE=os.path.join(os.getcwd(),"executable")
def free(): s=socket.socket(); s.bind(("127.0.0.1",0)); p=s.getsockname()[1]; s.close(); return p
def test(desc, setup, args):
    td=tempfile.mkdtemp(); setup(td); port=free()
    # replace PORT placeholder
    args=[a.replace("PORT",str(port)) for a in args]
    print(f"=== {desc} port={port} args={args} td={td}")
    proc=subprocess.Popen([EXE]+args, cwd=td, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    time.sleep(1.2); print("poll",proc.poll())
    paths=["/","/index.html","/myproj","/myproj/","/myproj/index.html","/myproj/hello.txt","//","/myproj//hello.txt","/myproj/sub/","/myproj/sub/page.html","/myproj/sub","/favicon.ico","/myproj/favicon.ico","/%2e%2e/oranda.json","/../oranda.json"]
    for path in paths:
        try:
            req=urllib.request.Request(f"http://127.0.0.1:{port}{path}")
            with urllib.request.urlopen(req, timeout=2) as r:
                print(path, r.status, r.headers.get("content-type"), r.read()[:200])
        except urllib.error.HTTPError as e:
            print(path, e.code, e.read()[:200])
        except Exception as e:
            print(path,"ERR",e)
    # HEAD, POST ?
    for meth in ["HEAD","POST","PUT"]:
        try:
            req=urllib.request.Request(f"http://127.0.0.1:{port}/myproj/", method=meth)
            with urllib.request.urlopen(req, timeout=2) as r: print(meth, r.status, r.read()[:100])
        except urllib.error.HTTPError as e: print(meth, e.code, e.read()[:100])
        except Exception as e: print(meth,"ERR",e)
    # range
    try:
        req=urllib.request.Request(f"http://127.0.0.1:{port}/myproj/hello.txt", headers={"Range":"bytes=0-4"})
        with urllib.request.urlopen(req, timeout=2) as r: print("RANGE",r.status, dict(r.headers), r.read())
    except Exception as e: print("RANGE ERR",e)
    proc.terminate()
    try: out,err=proc.communicate(timeout=3)
    except: proc.kill(); out,err=proc.communicate()
    print("OUT:",out); print("ERR:",err); print("exit",proc.returncode); print()

def s(td):
    p=pathlib.Path(td,"public"); p.mkdir(); (p/"index.html").write_text("<h1>Home</h1>"); (p/"hello.txt").write_text("hello world"); sub=p/"sub"; sub.mkdir(); (sub/"page.html").write_text("<p>sub</p>"); (sub/"index.html").write_text("<p>subindex</p>")
    pathlib.Path(td,"oranda.json").write_text('{"build":{"dist_dir":"public","path_prefix":"myproj"}}')
test("prefix",s,["serve","--port","PORT"])

def s2(td):
    p=pathlib.Path(td,"customdist"); p.mkdir(); (p/"index.html").write_text("CUSTOM")
    pathlib.Path(td,"oranda.json").write_text('{"build":{"dist_dir":"customdist"}}')
test("custom dist",s2,["serve","--port","PORT"])

def s3(td):
    p=pathlib.Path(td,"public"); p.mkdir(); (p/"index.html").write_text("HOME")
    pathlib.Path(td,"oranda.json").write_text('not json')
test("bad config serve",s3,["serve","--port","PORT"])

def s4(td):
    p=pathlib.Path(td,"public"); p.mkdir()
test("empty public no index",s4,["serve","--port","PORT"])
