    Diag(Box<Diag>),
}

#[derive(Clone, Debug)]
pub struct Diag {
    pub severity: Severity,
    pub message: String,
    pub causes: Vec<Cause>,
    pub snippet: Option<Snippet>,
    pub help: Option<String>,
}

impl Diag {
    pub fn error(message: impl Into<String>) -> Self {
        Self { severity: Severity::Error, message: message.into(), causes: Vec::new(), snippet: None, help: None }
    }
    pub fn warning(message: impl Into<String>) -> Self {
        Self { severity: Severity::Warning, message: message.into(), causes: Vec::new(), snippet: None, help: None }
    }
    pub fn with_cause(mut self, c: impl Into<String>) -> Self { self.causes.push(Cause::Text(c.into())); self }
    pub fn with_causes(mut self, cs: Vec<String>) -> Self { for c in cs { self.causes.push(Cause::Text(c)); } self }
    pub fn with_diag_cause(mut self, d: Diag) -> Self { self.causes.push(Cause::Diag(Box::new(d))); self }
    pub fn with_help(mut self, h: impl Into<String>) -> Self { self.help = Some(h.into()); self }
