}

pub type OrandaResult<T> = Result<T, Diag>;

// ---------- width / wrapping ----------
pub fn char_width(c: char) -> usize {
    match c {
        '\0'..='\x1f' | '\x7f' => 0,
        '\u{1100}'..='\u{115f}' | '\u{2e80}'..='\u{a4cf}' | '\u{ac00}'..='\u{d7a3}' | '\u{f900}'..='\u{faff}' | '\u{fe30}'..='\u{fe4f}' | '\u{ff00}'..='\u{ff60}' | '\u{ffe0}'..='\u{ffe6}' | '\u{1f300}'..='\u{1f64f}' | '\u{1f900}'..='\u{1f9ff}' | '\u{20000}'..='\u{3fffd}' => 2,
        _ => 1,
    }
}
pub fn disp_width(s: &str) -> usize { s.chars().map(char_width).sum() }

struct Atom { text: String, new_word: bool }

fn split_word_atoms(word: &str, first: bool) -> Vec<Atom> {
    // split after '/' and '-'
    let mut atoms = Vec::new();
    let mut cur = String::new();
    let chars: Vec<char> = word.chars().collect();
    for (i, ch) in chars.iter().enumerate() {
        cur.push(*ch);
        if (*ch == '/' || *ch == '-') && i + 1 < chars.len() {
            atoms.push(Atom { text: cur.clone(), new_word: first && atoms.is_empty() });
            cur.clear();
        }
    }
    if !cur.is_empty() {
        atoms.push(Atom { text: cur, new_word: first && atoms.is_empty() });
    }
    if atoms.is_empty() {
        atoms.push(Atom { text: String::new(), new_word: first });
    }
    // first atom of this word is new_word if this word is not the very first handled by caller; caller manages
    atoms
}

pub fn wrap_text(text: &str, first_indent: usize, cont_indent: usize, max_width: usize) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let logical: Vec<&str> = text.split('\n').collect();
    for (li, line) in logical.iter().enumerate() {
        let indent = if li == 0 { first_indent } else { cont_indent };
        let avail = max_width.saturating_sub(indent);
        if disp_width(line) <= avail {
            out.push(line.to_string());
            continue;
        }
        // leading spaces
        let mut leading = String::new();
        let mut rest_start = 0usize;
        for ch in line.chars() {
            if ch == ' ' { leading.push(ch); rest_start += 1; } else { break; }
        }
        let rest = &line[rest_start..];
        // atoms with word boundaries
        let mut atoms: Vec<Atom> = Vec::new();
        for (wi, word) in rest.split(' ').filter(|w| !w.is_empty()).enumerate() {
            let mut a = split_word_atoms(word, wi == 0);
            // mark first atom of word: new_word = (wi > 0)
            if !a.is_empty() { a[0].new_word = wi > 0; }
            atoms.extend(a);
        }
        let mut cur = leading.clone();
        let mut cur_w = disp_width(&cur);
        let mut cur_avail = avail;
        let mut first_in_line = true;
        for atom in atoms {
            let aw = disp_width(&atom.text);
            let sep = if atom.new_word && !first_in_line { 1 } else { 0 };
            if cur_w + sep + aw <= cur_avail {
                if sep == 1 { cur.push(' '); cur_w += 1; }
                cur.push_str(&atom.text); cur_w += aw; first_in_line = false;
            } else if aw <= max_width.saturating_sub(cont_indent) {
                // move to next line
                out.push(cur.clone());
                cur = atom.text.clone(); cur_w = aw; cur_avail = max_width.saturating_sub(cont_indent); first_in_line = false;
            } else {
                // hard break atom
                let mut remaining: Vec<char> = atom.text.chars().collect();
                if !first_in_line || cur.trim().len() > 0 {
                    // move to fresh line first (word longer than line)
                    if cur_w > 0 && !(first_in_line && cur.trim().is_empty()) {
                        out.push(cur.clone());
                        cur = String::new(); cur_w = 0; cur_avail = max_width.saturating_sub(cont_indent); first_in_line = true;
                    }
                }
                while !remaining.is_empty() {
                    let space = cur_avail.saturating_sub(cur_w);
                    if space == 0 {
                        out.push(cur.clone()); cur = String::new(); cur_w = 0; cur_avail = max_width.saturating_sub(cont_indent); continue;
                    }
                    let mut take = 0usize; let mut w = 0usize;
                    for ch in remaining.iter() {
                        let cw = char_width(*ch);
                        if w + cw > space { break; }
                        w += cw; take += 1;
                    }
                    if take == 0 {
                        out.push(cur.clone()); cur = String::new(); cur_w = 0; cur_avail = max_width.saturating_sub(cont_indent); continue;
                    }
                    let chunk: String = remaining.drain(..take).collect();
                    cur.push_str(&chunk); cur_w += w; first_in_line = false;
                    if !remaining.is_empty() {
                        out.push(cur.clone()); cur = String::new(); cur_w = 0; cur_avail = max_width.saturating_sub(cont_indent); first_in_line = true;
                    }
                }
            }
        }
        out.push(cur);
    }
    if out.is_empty() { out.push(String::new()); }
    out
}

// ---------- snippet ----------
fn expand_line(line: &str) -> String {
    let mut out = String::new();
    let mut col = 0usize;
    for ch in line.chars() {
        if ch == '\t' {
            let n = 4 - (col % 4);
            for _ in 0..n { out.push(' '); }
            col += n;
        } else {
            out.push(ch);
            col += char_width(ch);
        }
    }
    out
}

fn render_snippet(s: &Snippet, color: bool) -> Vec<String> {
    let offset = match s.offset { Some(o) => o, None => return Vec::new() };
    if offset >= s.source.len() { return Vec::new(); }
    // line starts
    let bytes = s.source.as_bytes();
    let mut starts: Vec<usize> = vec![0];
    for (i, b) in bytes.iter().enumerate() {
        if *b == b'\n' && i + 1 < bytes.len() { starts.push(i + 1); }
        // if source ends with \n, there is no extra displayable line for snippet purposes (offset < len ensures line exists)
    }
    // determine line idx
    let mut line_idx = 0usize;
    for (i, st) in starts.iter().enumerate() { if *st <= offset { line_idx = i; } else { break; } }
    // extract line texts
    let get_line = |idx: usize| -> String {
        let start = starts[idx];
        let end = if idx + 1 < starts.len() { starts[idx + 1] - 1 } else { s.source.len() };
        // end is index of \n or len; strip trailing \r and also if next start logic when last line had \n at end? need handle
        let mut e = end;
        // if this line is not last in starts, end points at \n char position (starts[next]-1) correct
        // if last and source ends without \n, e = len
        let slice = &s.source[start..e.min(s.source.len())];
        let slice = slice.strip_suffix('\r').unwrap_or(slice).strip_suffix('\n').unwrap_or(slice.strip_suffix('\r').unwrap_or(slice));
        slice.to_string()
    };
    // Lines count: count lines using Rust lines() logic approximated by starts but handle trailing newline: if source ends with \n, last starts entry excluded above.
    let total_lines = starts.len();
    let from = line_idx.saturating_sub(1);
    let to = std::cmp::min(line_idx + 1, total_lines.saturating_sub(1));
    let max_no = to + 1;
    let mw = format!("{}", max_no).len();
    let mut lines: Vec<String> = Vec::new();
    let gutter_pad = " ".repeat(mw + 2);
    if color {
        lines.push(format!("{}╭─[\x1b[36;1;4m{}\x1b[0m:{}:1]", gutter_pad, s.filename, from + 1));
    } else {
        lines.push(format!("{}╭─[{}:{}:1]", gutter_pad, s.filename, from + 1));
    }
    for idx in from..=to {
        let raw = get_line(idx);
        let expanded = expand_line(&raw);
        let no = idx + 1;
        if color {
            let pad = " ".repeat(mw - format!("{}", no).len() + 1);
            lines.push(format!("{}\x1b[2m{}\x1b[0m │ {}", pad, no, expanded));
        } else {
            let num = format!("{:>width$}", no, width = mw);
            lines.push(format!(" {} │ {}", num, expanded));
        }
        if idx == line_idx {
            // compute display col up to offset within line
            let line_start = starts[idx];
            let byte_col = offset.saturating_sub(line_start);
            // chars before offset in raw
            let mut dcol = 0usize;
            let mut consumed = 0usize;
            let mut hl_width = 1usize;
            for ch in raw.chars() {
                if consumed >= byte_col {
                    if ch == '\t' { hl_width = 4 - (dcol % 4); } else { hl_width = char_width(ch); if hl_width == 0 { hl_width = 1; } }
                    break;
                }
                if ch == '\t' { let n = 4 - (dcol % 4); dcol += n; } else { dcol += char_width(ch); }
                consumed += ch.len_utf8();
            }
            let spaces = " ".repeat(dcol);
            let dashes = "─".repeat(hl_width);
            if color {
                lines.push(format!("{}· \x1b[35;1m{}{}\x1b[0m", gutter_pad, spaces, dashes));
            } else {
                lines.push(format!("{}· {}{}", gutter_pad, spaces, dashes));
            }
        }
    }
    lines.push(format!("{}╰────", gutter_pad));
    lines
}

// ---------- rendering ----------
fn sev_symbol(sev: Severity) -> &'static str { match sev { Severity::Error => "×", Severity::Warning => "⚠" } }
fn sev_color(sev: Severity) -> &'static str { match sev { Severity::Error => "31", Severity::Warning => "33" } }

fn prefix_colored(color: bool, code: &str, plain: &str) -> String {
    if color { format!("\x1b[{}m{}\x1b[0m", code, plain) } else { plain.to_string() }
}

fn header_prefix_first(sev: Severity, color: bool) -> String {
    let sym = sev_symbol(sev);
    if color { format!("  \x1b[{}m{}\x1b[0m ", sev_color(sev), sym) } else { format!("  {} ", sym) }
}
fn header_prefix_cont(sev: Severity, color: bool) -> String {
    if color { format!("  \x1b[{}m│\x1b[0m ", sev_color(sev)) } else { "  │ ".to_string() }
}

fn render_diag_lines(d: &Diag, color: bool, show_causes: bool, max_width: usize) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    // header
    let first_p = header_prefix_first(d.severity, color);
    let cont_p = header_prefix_cont(d.severity, color);
    let wrapped = wrap_text(&d.message, 4, 4, max_width);
    for (i, w) in wrapped.iter().enumerate() {
        if i == 0 { out.push(format!("{}{}", first_p, w)); } else { out.push(format!("{}{}", cont_p, w)); }
    }
    if show_causes {
        let code = sev_color(d.severity);
        let n = d.causes.len();
        for (i, cause) in d.causes.iter().enumerate() {
            let is_last = i + 1 == n;
            let branch_plain = if is_last { "  ╰─▶ " } else { "  ├─▶ " };
            let cont_plain = if is_last { "      " } else { "  │   " };
            let branch = prefix_colored(color, code, branch_plain);
            let cont = prefix_colored(color, code, cont_plain);
            match cause {
                Cause::Text(txt) => {
                    let ws = wrap_text(txt, 6, 6, max_width);
                    for (j, w) in ws.iter().enumerate() {
                        if j == 0 { out.push(format!("{}{}", branch, w)); } else { out.push(format!("{}{}", cont, w)); }
                    }
                }
                Cause::Diag(inner) => {
                    let inner_lines = render_diag_lines(inner, color, false, max_width.saturating_sub(6));
                    for (j, l) in inner_lines.iter().enumerate() {
                        if j == 0 { out.push(format!("{}{}", branch, l)); } else { out.push(format!("{}{}", cont, l)); }
                    }
                    // trailing blank line from inner diagnostic
                    out.push(cont.clone());
                }
            }
        }
    }
    if let Some(snip) = &d.snippet {
        out.extend(render_snippet(snip, color));
    }
    if let Some(help) = &d.help {
        let ws = wrap_text(help, 8, 8, max_width);
        for (j, w) in ws.iter().enumerate() {
            if j == 0 {
                if color { out.push(format!("\x1b[36m  help: \x1b[0m{}", w)); } else { out.push(format!("  help: {}", w)); }
            } else {
                out.push(format!("        {}", w));
            }
        }
    }
    out
}

pub fn render(d: &Diag, color: bool) -> String {
    let lines = render_diag_lines(d, color, true, 118);
    let mut s = lines.join("\n");
    s.push('\n');
    s
}

pub fn eprint_diag(d: &Diag) {
    let c = stderr_color();
    eprint!("{}", render(d, c));
    eprintln!();
}

// ---------- JSON ----------
fn json_escape(s: &str) -> String { serde_json::to_string(s).unwrap() }

fn diag_causes_json(d: &Diag) -> Vec<String> {
    let mut v = Vec::new();
    for c in &d.causes {
        match c {
            Cause::Text(t) => v.push(t.clone()),
            Cause::Diag(inner) => {
                v.push(inner.message.clone());
                v.extend(diag_causes_json(inner));
            }
        }
    }
    v
}

pub fn diag_json_value(d: &Diag) -> serde_json::Value {
    // Build object preserving insertion order via serde_json Map with preserve_order?? serde_json Map is BTree by default unless preserve_order feature.
    // We construct string manually instead in to_json_output.
    let _ = d;
    serde_json::Value::Null
}

pub fn to_json_output(d: &Diag) -> String {
    let causes = diag_causes_json(d);
    let causes_s = causes.iter().map(|c| json_escape(c)).collect::<Vec<_>>().join(",");
    let sev = match d.severity { Severity::Error => "error", Severity::Warning => "warning" };
    let mut obj = String::new();
    obj.push_str(&format!("{{\"message\": {},\"severity\": {},\"causes\": [{}]", json_escape(&d.message), json_escape(sev), causes_s));
    if let Some(h) = &d.help {
        obj.push_str(&format!(",\"help\": {}", json_escape(h)));
    }
    if let Some(snip) = &d.snippet {
        let valid = snip.offset.map(|o| o < snip.source.len()).unwrap_or(false);
        if valid {
            obj.push_str(&format!(",\"filename\": {}", json_escape(&snip.filename)));
            obj.push_str(&format!(",\"labels\": [{{\"span\": {{\"offset\": {},\"length\": {}}}}}]", snip.offset.unwrap(), snip.length));
        } else {
            obj.push_str(",\"filename\": \"\",\"labels\": []");
        }
    } else {
        obj.push_str(",\"labels\": []");
    }
    obj.push_str(",\"related\": []}");
    format!("{{\"diagnostic\": {}}}", obj)
}

pub fn print_fatal(d: &Diag) {
    if output_is_json() {
        println!("{}", to_json_output(d));
        use std::io::Write; let _ = std::io::stdout().flush();
    }
    eprint_diag(d);
}

pub fn panic_diag(location: &str, payload: &str) -> Diag {
    let mut causes = vec![format!("at {}", location), payload.to_string()];
    // backtrace handling: if RUST_BACKTRACE set and not 0, append backtrace lines to payload cause as original does (payload line followed by indented frames)
    if let Ok(v) = std::env::var("RUST_BACKTRACE") {
        if v != "0" && !v.is_empty() {
            let bt = std::backtrace::Backtrace::force_capture();
            let bt_s = format!("{}", bt);
            // transform bt lines to similar indented style, appended to second cause
            if causes.len() >= 2 {
                let mut extra = String::new();
                for line in bt_s.lines() { extra.push('\n'); extra.push_str(line); }
                causes[1].push_str(&extra);
            }
        }
    }
    Diag::error("oranda panicked.").with_causes(causes).with_help("set the `RUST_BACKTRACE=1` environment variable to display a backtrace.")
}

pub fn print_panic(location: &str, payload: &str) {
    let d = panic_diag(location, payload);
    if output_is_json() {
        println!("{}", to_json_output(&d));
        use std::io::Write; let _ = std::io::stdout().flush();
    }
    eprint_diag(&d);
}

pub fn install_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        let location = if let Some(loc) = info.location() {
            format!("{}:{}:{}", loc.file(), loc.line(), loc.column())
        } else { "unknown".to_string() };
        let payload = if let Some(s) = info.payload().downcast_ref::<&str>() {
            s.to_string()
        } else if let Some(s) = info.payload().downcast_ref::<String>() {
            s.clone()
        } else {
            "Box<dyn Any>".to_string()
        };
        print_panic(&location, &payload);
    }));
}

// logging
fn log_line(symbol: &str, level: &str, msg: &str, sym_color: &str, msg_color: &str) {
    if stdout_color() {
        println!("\x1b[{}m\x1b[1m{}\x1b[0m >o_o< {}: \x1b[{}m\x1b[1m{}\x1b[0m", sym_color, symbol, level, msg_color, msg);
    } else {
        println!("{} >o_o< {}: {}", symbol, level, msg);
    }
    use std::io::Write; let _ = std::io::stdout().flush();
}
pub fn log_debug(msg: &str) { if verbose() { log_line("↪", "DEBUG", msg, "37", "35"); } }
pub fn log_info(msg: &str) { log_line("↪", "INFO", msg, "37", "37"); }
pub fn log_warn(msg: &str) { log_line("⚠", "WARNING", msg, "33", "33"); }
pub fn log_success(msg: &str) { log_line("✓", "SUCCESS", msg, "32", "32"); }
RS
