// ---------- Ordered map ----------
#[derive(Clone, Debug, Default)]
pub struct OrderedStringMap(pub Vec<(String, String)>);
impl OrderedStringMap {
    pub fn is_empty(&self) -> bool { self.0.is_empty() }
    pub fn get(&self, k: &str) -> Option<&str> { self.0.iter().find(|(kk, _)| kk == k).map(|(_, v)| v.as_str()) }
}
struct OMapVisitor;
impl<'de> Visitor<'de> for OMapVisitor {
    type Value = OrderedStringMap;
    fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result { write!(f, "a map") }
    fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> Result<Self::Value, A::Error> {
        let mut v: Vec<(String, String)> = Vec::new();
        while let Some((k, val)) = map.next_entry::<String, String>()? {
            if let Some(existing) = v.iter_mut().find(|(kk, _)| *kk == k) { existing.1 = val; } else { v.push((k, val)); }
        }
        Ok(OrderedStringMap(v))
    }
}
impl<'de> Deserialize<'de> for OrderedStringMap {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> { d.deserialize_map(OMapVisitor) }
}

