    match std::fs::read_to_string(path) {
        Ok(contents) => {
            let layer: OrandaLayer = serde_json::from_str(&contents)
                .map_err(|e| parse_json_diag(&contents, "./oranda.json", &e))?;
            Ok((Some(layer), true))
        }
        Err(_) => Ok((None, false)),
    }
}

pub fn load_config() -> OrandaResult<Config> {
    let (layer_opt, has_file) = load_oranda_layer()?;
    if layer_opt.is_none() {
        log_debug("No config found, using default values");
    }
    let layer = layer_opt.unwrap_or_default();
    // project detection
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let detected = crate::project::detect_project(&cwd);
    let (proj_info, _cargo_dist) = detected;
    let dist_dir = layer.build.as_ref().and_then(|b| b.dist_dir.clone()).unwrap_or_else(|| "public".to_string());
    let static_dir = layer.build.as_ref().and_then(|b| b.static_dir.clone());
    let path_prefix = layer.build.as_ref().and_then(|b| b.path_prefix.clone());
    let readme_path = if let Some(rp) = layer.project.as_ref().and_then(|p| p.readme_path.clone()) {
        rp
    } else if let Some(rp) = &proj_info.readme_path {
        rp.clone()
    } else {
        "README.md".to_string()
    };
    let additional_pages = layer.build.as_ref().and_then(|b| b.additional_pages.clone()).map(|m| m.0).unwrap_or_default();
    let config_name = layer.project.as_ref().and_then(|p| p.name.clone()).or_else(|| proj_info.name.clone()).unwrap_or_else(|| "My Oranda Project".to_string());
    let cfg = Config {
        layer,
        has_oranda_file: has_file,
        project: proj_info,
        config_name,
        dist_dir,
        static_dir,
        path_prefix,
        readme_path,
        additional_pages,
    };
    // funding preferred check
    if cfg.funding_enabled() {
        let fl = cfg.funding_layer();
        if fl.preferred_funding.is_some() {
            let mut candidates: Vec<String> = vec![".github/FUNDING.yml".to_string(), "funding.md".to_string()];
            if let Some(p) = &fl.md_path { candidates.push(p.clone()); }
            if let Some(p) = &fl.yml_path { candidates.push(p.clone()); }
            let any_exists = candidates.iter().any(|c| Path::new(c).exists());
            if !any_exists {
                return Err(Diag::error("Couldn't find your FUNDING.yml or funding.md").with_help("You can manually specify md_path or yml_path in your components.funding config"));
            }
        }
    }
    Ok(cfg)
}

// asset errors helpers
pub fn read_asset_diag(path_display: &str, e: &std::io::Error) -> Diag {
    Diag::error(format!("failed to read asset from {}", path_display))
        .with_cause(format!("{}", e))
        .with_help("Make sure your path is relative to your oranda config or project manifest file.")
}
pub fn write_new_asset_diag(path_display: &str, e: &std::io::Error) -> Diag {
    Diag::error(format!("failed to write a new asset to {}.", path_display))
        .with_cause(format!("{}", e))
        .with_help("Make sure you have the correct permissions to create a new file.")
}
pub fn write_new_asset(contents: &str, dest: &Path) -> OrandaResult<()> {
    let display = dest.display().to_string();
    if let Some(parent) = dest.parent() {
        if !parent.as_os_str().is_empty() {
            std::fs::create_dir_all(parent).map_err(|e| write_new_asset_diag(&display, &e))?;
        }
    }
    std::fs::write(dest, contents).map_err(|e| write_new_asset_diag(&display, &e))
}
