// ---------- parse error diagnostic ----------
pub fn parse_json_diag(source: &str, filename: &str, err: &serde_json::Error) -> Diag {
    let col = err.column();
    let line = err.line();
    let offset = if col == 0 {
        None
    } else {
        // compute byte offset from line/col (col is 1-based byte column)
        let mut off = 0usize;
        let mut cur_line = 1usize;
        let bytes = source.as_bytes();
        let mut idx = 0usize;
        while cur_line < line && idx < bytes.len() {
            if bytes[idx] == b'\n' { cur_line += 1; }
            idx += 1;
            off = idx;
            if cur_line == line { break; }
        }
        Some(off + (col - 1))
    };
    // If offset out of range, mark None (filename becomes empty in JSON)
    let offset_valid = offset.filter(|o| *o < source.len());
    let snippet = Snippet {
        filename: filename.to_string(),
        source: source.to_string(),
        offset: offset_valid.or(offset).filter(|_| offset_valid.is_some()),
        length: 1,
    };
    // Preserve presence of snippet record but with offset None if invalid, so JSON has filename ""
    Diag::error("failed to parse JSON").with_cause(format!("{}", err)).with_snippet(snippet)
}

