    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let detected = crate::project::detect_project(&cwd);
    let (proj_info, _cargo_dist) = detected;
    let dist_dir = layer.build.as_ref().and_then(|b| b.dist_dir.clone()).unwrap_or_else(|| "public".to_string());
    let static_dir = layer.build.as_ref().and_then(|b| b.static_dir.clone());
    let path_prefix = layer.build.as_ref().and_then(|b| b.path_prefix.clone());
    let readme_path = if let Some(rp) = layer.project.as_ref().and_then(|p| p.readme_path.clone()) {
        rp
    } else if let Some(rp) = &proj_info.readme_path {
        rp.clone()
    } else {
        "README.md".to_string()
    };
    let additional_pages = layer.build.as_ref().and_then(|b| b.additional_pages.clone()).map(|m| m.0).unwrap_or_default();
    let config_name = layer.project.as_ref().and_then(|p| p.name.clone()).or_else(|| proj_info.name.clone()).unwrap_or_else(|| "My Oranda Project".to_string());
    let cfg = Config {
        layer,
        has_oranda_file: has_file,
        project: proj_info,
        config_name,
        dist_dir,
        static_dir,
        path_prefix,
        readme_path,
        additional_pages,
    };
    // funding preferred check
    if cfg.funding_enabled() {
        let fl = cfg.funding_layer();
        if fl.preferred_funding.is_some() {
            let mut candidates: Vec<String> = vec![".github/FUNDING.yml".to_string(), "funding.md".to_string()];
            if let Some(p) = &fl.md_path { candidates.push(p.clone()); }
            if let Some(p) = &fl.yml_path { candidates.push(p.clone()); }
            let any_exists = candidates.iter().any(|c| Path::new(c).exists());
            if !any_exists {
                return Err(Diag::error("Couldn't find your FUNDING.yml or funding.md").with_help("You can manually specify md_path or yml_path in your components.funding config"));
            }
        }
    }
    Ok(cfg)
}

