// Version parsing (lenient npm)
pub fn parse_js_version(s: &str) -> Result<String, ()> {
    // trim leading whitespace (space/tab/newline?)
    let mut t = s.trim_start_matches(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r');
    if let Some(stripped) = t.strip_prefix('v').or_else(|| t.strip_prefix('V')) { t = stripped; }
    // split build
    let (main_part, build_part) = match t.split_once('+') {
        Some((a, b)) => (a, Some(b)),
        None => (t, None),
    };
    let (core_part, pre_part) = match main_part.split_once('-') {
        Some((a, b)) => (a, Some(b)),
        None => (main_part, None),
    };
    let core: Vec<&str> = core_part.split('.').collect();
    if core.len() != 3 { return Err(()); }
    let mut nums: Vec<u64> = Vec::new();
    for c in &core {
        if c.is_empty() || !c.chars().all(|ch| ch.is_ascii_digit()) { return Err(()); }
        nums.push(c.parse::<u64>().map_err(|_| ())?);
    }
    let mut out = format!("{}.{}.{}", nums[0], nums[1], nums[2]);
    if let Some(pre) = pre_part {
        if pre.is_empty() { return Err(()); }
        let mut parts: Vec<String> = Vec::new();
        for id in pre.split('.') {
            if id.is_empty() || !id.chars().all(|ch| ch.is_ascii_alphanumeric() || ch == '-') { return Err(()); }
            if id.chars().all(|ch| ch.is_ascii_digit()) {
                parts.push(format!("{}", id.parse::<u64>().map_err(|_| ())?));
            } else { parts.push(id.to_string()); }
        }
        out.push('-'); out.push_str(&parts.join("."));
    }
    if let Some(build) = build_part {
        if build.is_empty() { return Err(()); }
        for id in build.split('.') {
            if id.is_empty() || !id.chars().all(|ch| ch.is_ascii_alphanumeric() || ch == '-') { return Err(()); }
        }
        out.push('+'); out.push_str(build);
    }
    Ok(out)
}

fn deserialize_js_version<'de, D: Deserializer<'de>>(d: D) -> Result<Option<String>, D::Error> {
    // Custom visitor expecting "a version string"
    struct V;
    impl<'de> Visitor<'de> for V {
        type Value = Option<String>;
        fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result { write!(f, "a version string") }
        fn visit_str<E: serde::de::Error>(self, s: &str) -> Result<Self::Value, E> {
            match parse_js_version(s) { Ok(v) => Ok(Some(v)), Err(_) => Err(E::custom("Failed to parse version.")) }
        }
        fn visit_string<E: serde::de::Error>(self, s: String) -> Result<Self::Value, E> { self.visit_str(&s) }
        fn visit_none<E: serde::de::Error>(self) -> Result<Self::Value, E> { Ok(None) }
        fn visit_unit<E: serde::de::Error>(self) -> Result<Self::Value, E> { Ok(None) }
        fn visit_some<D2: Deserializer<'de>>(self, d2: D2) -> Result<Self::Value, D2::Error> {
            // This won't be used as we use deserialize_any below?
            let s = String::deserialize(d2)?;
            match parse_js_version(&s) { Ok(v) => Ok(Some(v)), Err(_) => Err(serde::de::Error::custom("Failed to parse version.")) }
        }
    }
    // deserialize_any will call visit_str for strings, visit_i64 etc for others giving invalid type with expecting message
    d.deserialize_any(V)
}

