}

impl<'de> Deserialize<'de> for Manifest {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        struct MV;
        impl<'de> Visitor<'de> for MV {
            type Value = Manifest;
            fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result { write!(f, "struct Manifest") }
            fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> Result<Self::Value, A::Error> {
                let mut m = Manifest::default();
                // track duplicate known fields close to derive behaviour
                let mut seen: Vec<String> = Vec::new();
                while let Some(k) = map.next_key::<String>()? {
                    macro_rules! get {
                        ($field:ident) => {{
                            if seen.contains(&k) { return Err(serde::de::Error::duplicate_field(Box::leak(k.clone().into_boxed_str()) as &'static str)); }
                            seen.push(k.clone());
                            m.$field = map.next_value()?;
                        }};
                    }
                    match k.as_str() {
                        "name" => get!(name),
                        "version" => {
                            if seen.contains(&k) { return Err(serde::de::Error::duplicate_field("version")); }
                            seen.push(k.clone());
                            // use seed for custom version
                            m.version = map.next_value_seed(VersionSeed)?;
                        },
                        "description" => get!(description),
                        "keywords" => get!(keywords),
                        "homepage" => get!(homepage),
                        "bugs" => get!(bugs),
                        "license" => get!(license),
                        "author" => get!(author),
                        "contributors" => get!(contributors),
                        "files" => get!(files),
                        "main" => get!(main),
                        "bin" => get!(bin),
                        "man" => get!(man),
                        "repository" => get!(repository),
                        "scripts" => get!(scripts),
                        "dependencies" => get!(dependencies),
                        "devDependencies" => get!(dev_dependencies),
                        "peerDependencies" => get!(peer_dependencies),
                        "optionalDependencies" => get!(optional_dependencies),
                        "bundleDependencies" => get!(bundle_dependencies),
                        "bundledDependencies" => get!(bundled_dependencies),
                        "os" => get!(os),
                        "cpu" => get!(cpu),
                        "private" => get!(private),
                        "publishConfig" => get!(publish_config),
                        "workspaces" => get!(workspaces),
                        "type" => get!(type_),
                        _ => { let _ = map.next_value::<serde::de::IgnoredAny>()?; }
                    }
                }
                Ok(m)
            }
        }
        d.deserialize_map(MV)
    }
}
struct VersionSeed;
impl<'de> serde::de::DeserializeSeed<'de> for VersionSeed {
    type Value = Option<String>;
    fn deserialize<D: Deserializer<'de>>(self, d: D) -> Result<Self::Value, D::Error> { deserialize_js_version(d) }
}

// Path string custom (camino-like)
#[derive(Clone, Debug)]
pub struct PathString(pub String);
struct PSVisitor;
impl<'de> Visitor<'de> for PSVisitor {
    type Value = PathString;
    fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result { write!(f, "path string") }
    fn visit_str<E: serde::de::Error>(self, s: &str) -> Result<Self::Value, E> { Ok(PathString(s.to_string())) }
    fn visit_string<E: serde::de::Error>(self, s: String) -> Result<Self::Value, E> { Ok(PathString(s)) }
}
impl<'de> Deserialize<'de> for PathString {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> { d.deserialize_any(PSVisitor) }
}

