fn transform_repo_string(s: &str) -> Option<String> {
    // hosted-git-info shortcut/url handling
    // strip committish fragment for shortcut form
    let (before_hash, _frag) = match s.split_once('#') { Some((a, _)) => (a, ()), None => (s, ()) };
    let s_nofrag = before_hash;
    if s_nofrag.contains("://") {
        let (scheme, rest) = s_nofrag.split_once("://")?;
        let allowed = ["git", "git+ssh", "git+https", "git+http"];
        if !allowed.contains(&scheme) { return None; }
        // parse with url crate after converting scheme to https for parsing host/path
        let as_https = format!("https://{}", rest);
        let u = url::Url::parse(&as_https).ok()?;
        let host = u.host_str()?;
        let path = u.path().trim_matches('/');
        if path.is_empty() { return None; }
        let mut out = format!("https://{}/{}", host, path);
        if !out.ends_with(".git") { out.push_str(".git"); }
        return Some(out);
    }
    // shortcut: [platform:]user/project...
    if s_nofrag.contains('@') || s_nofrag.starts_with('/') { return None; }
    let (platform, remainder) = if let Some((p, r)) = s_nofrag.split_once(':') {
        (p, r)
    } else { ("github", s_nofrag) };
    if !["github", "gitlab", "bitbucket", "gist"].contains(&platform) { return None; }
    // remainder must contain a '/'
    let first_slash = remainder.find('/')?;
    let user = &remainder[..first_slash];
    let projpath = &remainder[first_slash + 1..];
    // validation similar to hosted-git-info: user non-empty and no odd chars
    if user.is_empty() || projpath.is_empty() { return None; }
    if !user.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_' || c == '.') { return None; }
    // projpath can contain slashes - hosted-git regex requires at least one char after slash, no spaces
    if projpath.contains(char::is_whitespace) { return None; }
    match platform {
        "github" => Some(format!("https://github.com/{}.git", remainder)),
        "gitlab" => Some(format!("https://gitlab.com/{}.git", remainder)),
        "bitbucket" => Some(format!("https://bitbucket.com/{}.git", remainder)),
        "gist" => Some(format!("https://gist.github.com/{}.git", projpath)),
        _ => None,
    }
}

enum JsErrorKind {
    Diag(Diag, Vec<String>), // inner diag + extra causes flattened
}

fn detect_js(cwd: &Path) -> Option<Result<ProjectInfo, Diag>> {
    let manifest_path = cwd.join("package.json");
    if !manifest_path.is_file() { return None; }
    let manifest_abs = manifest_path.display().to_string();
    let contents = match std::fs::read_to_string(&manifest_path) {
        Ok(c) => c,
        Err(e) => {
            let inner = crate::config::read_asset_diag(&manifest_abs, &e);
            // inner for asset errors: message from inner is already "failed to read asset from ..." with help, and its cause is io error as extra flattened cause.
            // Construct warning: inner diag without its cause, extra causes = [io error]
            let mut inner2 = inner.clone();
            let extra: Vec<String> = inner2.causes.iter().filter_map(|c| if let Cause::Text(t) = c { Some(t.clone()) } else { None }).collect();
            inner2.causes.clear();
            return Some(Err(warning_diag("javascript", &manifest_abs, inner2, extra)));
        }
    };
    let manifest: Manifest = match serde_json::from_str(&contents) {
        Ok(m) => m,
        Err(e) => {
            // failed to parse JSON diag with filename absolute
            let mut inner = parse_json_diag(&contents, &manifest_abs, &e);
            // move its cause to extra
            let extra: Vec<String> = inner.causes.iter().filter_map(|c| if let Cause::Text(t) = c { Some(t.clone()) } else { None }).collect();
            inner.causes.clear();
            return Some(Err(warning_diag("javascript", &manifest_abs, inner, extra)));
        }
    };
    if manifest.name.is_none() {
        let inner = Diag::error(format!("your package doesn't have a name: {}", manifest_abs)).with_help("is it a workspace? We don't support that yet.");
        return Some(Err(warning_diag("javascript", &manifest_abs, inner, vec![])));
    }
    // binaries reparse
    let reparse: BinReparse = match serde_json::from_str(&contents) {
        Ok(v) => v,
        Err(e) => {
            let inner = Diag::error(format!("Failed to read the binaries from your package.json: {}", manifest_abs));
            return Some(Err(warning_diag("javascript", &manifest_abs, inner, vec![format!("{}", e)])));
        }
    };
    // binaries list (currently not used except to cause IO errors for directories.bin when bin is None)
    if manifest.bin.is_none() {
        if let Some(dirs) = &reparse.directories {
            if let Some(bin_path) = &dirs.bin {
                let p = &bin_path.0;
                let path_obj = Path::new(p);
                // If it is a file (following), fine. Else attempt read_dir.
                if !path_obj.is_file() {
                    // read_dir on the raw path (relative to cwd)
                    match std::fs::read_dir(path_obj) {
                        Ok(mut it) => {
                            // consume? iterate - errors on iteration use fs-err style too - simplified: try collect
                            if let Err(e) = it.try_for_each(|_| Ok::<(), std::io::Error>(())) {
                                let _ = e;
                            }
                        }
                        Err(e) => {
                            let inner = Diag::error(format!("Failed to read the binaries from your package.json: {}", manifest_abs));
                            let first = format!("IO error for operation on {}: {}", p, e);
                            let second = format!("{}", e);
                            return Some(Err(warning_diag("javascript", &manifest_abs, inner, vec![first, second])));
                        }
                    }
                }
            }
        }
    }
    let repository = match &manifest.repository {
        Some(Repository::Shortcut(s)) => transform_repo_string(s),
        Some(Repository::Info(info)) => info.url.clone(),
        None => None,
    };
    let readme_path = find_readme(cwd);
    Some(Ok(ProjectInfo {
        name: manifest.name.clone(),
        version: manifest.version.clone(),
        description: manifest.description.clone(),
        homepage: manifest.homepage.clone(),
        repository,
        license: manifest.license.clone(),
        readme_path,
        cargo_dist_detected: false,
    }))
}

pub fn detect_project(cwd: &Path) -> (ProjectInfo, bool) {
    let mut chosen: Option<ProjectInfo> = None;
    if let Some(res) = detect_rust(cwd) {
        match res {
            Ok(p) => { chosen = Some(p); }
            Err(w) => { eprint_diag(&w); }
        }
    }
    if let Some(res) = detect_js(cwd) {
        match res {
            Ok(p) => {
                if chosen.is_some() {
                    log_warn(&format!("Also found a Javascript project at {}, but we're ignoring it", abs_string(cwd, "package.json")));
                } else {
                    chosen = Some(p);
                }
            }
            Err(w) => { eprint_diag(&w); }
        }
    }
    let proj = chosen.unwrap_or(ProjectInfo { name: None, version: None, description: None, homepage: None, repository: None, license: None, readme_path: None, cargo_dist_detected: false });
    let cd = proj.cargo_dist_detected;
    (proj, cd)
}
RS
"}

actions.command:
cat > src/project.rs <<'RS'
use crate::config::*;
use crate::diag::*;
use serde::de::{MapAccess, Visitor};
use serde::{Deserialize, Deserializer};
use std::fmt;
use std::path::{Path, PathBuf};
use std::process::Command;

// ---------- generic helpers ----------
fn abs_path(cwd: &Path, rel: &str) -> PathBuf {
    let p = Path::new(rel);
    if p.is_absolute() { p.to_path_buf() } else { cwd.join(p) }
}
fn abs_string(cwd: &Path, rel: &str) -> String {
    abs_path(cwd, rel).display().to_string()
}

fn find_readme(root_abs: &Path) -> Option<String> {
    // search entries in root for file whose name starts with README (is_file following symlinks)
    let entries = std::fs::read_dir(root_abs).ok()?;
    for e in entries.flatten() {
        let name = e.file_name().to_string_lossy().to_string();
        if name.starts_with("README") {
            let p = e.path();
            if p.is_file() {
                // If symlink, original appears to canonicalize then make relative? special case to approximate observed:
                // If the found file is a symlink in the root, canonical target relative to root if inside root
                if let Ok(md) = std::fs::symlink_metadata(&p) {
                    if md.file_type().is_symlink() {
                        if let Ok(canon) = std::fs::canonicalize(&p) {
                            if let Ok(rel) = canon.strip_prefix(root_abs) {
                                return Some(rel.display().to_string());
                            }
                            return Some(canon.display().to_string());
                        }
                    }
                }
                return Some(p.display().to_string());
            }
        }
    }
    None
}

// ---------- Cargo ----------
fn warning_diag(kind: &str, manifest_abs: &str, inner: Diag, extra_causes: Vec<String>) -> Diag {
    let mut d = Diag::warning(format!("We found a potential {} project at {} but there was an issue", kind, manifest_abs));
    d = d.with_diag_cause(inner);
    for c in extra_causes { d.causes.push(Cause::Text(c)); }
    d
}

fn detect_rust(cwd: &Path) -> Option<Result<ProjectInfo, Diag>> {
    let manifest = cwd.join("Cargo.toml");
    if !manifest.is_file() { return None; }
    let manifest_abs = manifest.display().to_string();
    let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".to_string());
    let output = Command::new(&cargo)
        .args(["metadata", "--format-version", "1", "--no-deps", "--all-features"])
        .current_dir(cwd)
        .output();
    let inner_msg = "`cargo metadata` execution failed".to_string();
    let output = match output {
        Err(e) => {
            let io_s = format!("{}", e);
            let first = format!("failed to start `cargo metadata`: {}", io_s);
            let inner = Diag::error(inner_msg);
            return Some(Err(warning_diag("rust", &manifest_abs, inner, vec![first, io_s])));
        }
        Ok(o) => o,
    };
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
        let cause = format!("`cargo metadata` exited with an error: {}", stderr);
        // cargo_metadata error display: "exited with an error: {stderr}" where if stderr empty it ends with colon? Original for /bin/false: "`cargo metadata` exited with an error:" then blank . Their Display appears to be with a newline? Check: format in cargo_metadata crate is "`cargo metadata` exited with an error: {stderr}" - if stderr is "", cause ends with ": " maybe trimmed in display? Observed cause string in diag rendering: "`cargo metadata` exited with an error:" and then a blank line from diag print - suggests cause string is "...error: " or "...error:\n"? We'll approximate: if stderr empty, cause = "`cargo metadata` exited with an error:".to_string() ??? plus handling: use format! with stderr, if stderr empty trim_end? Let's produce: if stderr.is_empty() { "`cargo metadata` exited with an error:".to_string() } else { format!("`cargo metadata` exited with an error: {}", stderr) } but stderr typically ends with \n, keep it (render will add extra line)
        let cause = if stderr.is_empty() { "`cargo metadata` exited with an error:".to_string() } else { cause };
        let inner = Diag::error(inner_msg);
        return Some(Err(warning_diag("rust", &manifest_abs, inner, vec![cause])));
    }
    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    // find json line
    let json_line = stdout.lines().find(|l| l.trim_start().starts_with('{'));
    let json_line = match json_line {
        None => {
            let inner = Diag::error(inner_msg);
            return Some(Err(warning_diag("rust", &manifest_abs, inner, vec!["could not find any json in the output of `cargo metadata`".to_string()])));
        }
        Some(l) => l.to_string(),
    };
    let metadata: serde_json::Value = match serde_json::from_str(&json_line) {
        Ok(v) => v,
        Err(e) => {
            let inner = Diag::error(inner_msg);
            return Some(Err(warning_diag("rust", &manifest_abs, inner, vec![format!("{}", e)])));
        }
    };
    // parse packages
    let packages = metadata.get("packages").and_then(|v| v.as_array()).cloned().unwrap_or_default();
    let workspace_members: Vec<String> = metadata.get("workspace_members").and_then(|v| v.as_array()).map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect()).unwrap_or_default();
    let workspace_metadata = metadata.get("workspace_metadata").cloned().unwrap_or(serde_json::Value::Null);
    let cargo_dist_detected = workspace_metadata.get("dist").map(|v| !v.is_null()).unwrap_or(false);
    // root package: manifest_path == cwd/Cargo.toml
    let manifest_abs_norm = abs_path(cwd, "Cargo.toml");
    let mut chosen: Option<serde_json::Value> = None;
    for pkg in &packages {
        let id = pkg.get("id").and_then(|v| v.as_str()).unwrap_or("");
        if !workspace_members.iter().any(|m| m == id) && !workspace_members.is_empty() { continue; }
        let mp = pkg.get("manifest_path").and_then(|v| v.as_str()).unwrap_or("");
        if Path::new(mp) == manifest_abs_norm.as_path() {
            chosen = Some(pkg.clone());
            break;
        }
    }
    let pkg = match chosen {
        Some(p) => p,
        None => {
            // workspace with no root package: project is the workspace itself with no package fields, but detection succeeded
            return Some(Ok(ProjectInfo {
                name: None, version: None, description: None, homepage: None, repository: None, license: None,
                readme_path: None, // caller will use default README.md handling - but observed root README.md relative, which comes from default
                cargo_dist_detected: false, // even if workspace metadata dist exists, observations show no effect without root package
            }));
        }
    };
    let get_str = |k: &str| pkg.get(k).and_then(|v| v.as_str()).map(|s| s.to_string());
    let manifest_dir = Path::new(pkg.get("manifest_path").and_then(|v| v.as_str()).unwrap_or("Cargo.toml")).parent().map(|p| p.to_path_buf()).unwrap_or_else(|| cwd.to_path_buf());
    let readme_path = if let Some(r) = get_str("readme") {
        // cargo metadata readme is a path relative to manifest dir (or occasionally absolute?)
        // join to make absolute as original
        let rp = Path::new(&r);
        let abs = if rp.is_absolute() { rp.to_path_buf() } else { manifest_dir.join(rp) };
        Some(abs.display().to_string())
    } else {
        find_readme(&manifest_dir)
    };
    Some(Ok(ProjectInfo {
        name: get_str("name"),
        version: get_str("version"),
        description: get_str("description"),
        homepage: get_str("homepage"),
        repository: get_str("repository"),
        license: get_str("license"),
        readme_path,
        cargo_dist_detected,
    }))
}

// ---------- Javascript ----------
// Version parsing (lenient npm)
pub fn parse_js_version(s: &str) -> Result<String, ()> {
    // trim leading whitespace (space/tab/newline?)
    let mut t = s.trim_start_matches(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r');
    if let Some(stripped) = t.strip_prefix('v').or_else(|| t.strip_prefix('V')) { t = stripped; }
    // split build
    let (main_part, build_part) = match t.split_once('+') {
        Some((a, b)) => (a, Some(b)),
        None => (t, None),
    };
    let (core_part, pre_part) = match main_part.split_once('-') {
        Some((a, b)) => (a, Some(b)),
        None => (main_part, None),
    };
    let core: Vec<&str> = core_part.split('.').collect();
    if core.len() != 3 { return Err(()); }
    let mut nums: Vec<u64> = Vec::new();
    for c in &core {
        if c.is_empty() || !c.chars().all(|ch| ch.is_ascii_digit()) { return Err(()); }
        nums.push(c.parse::<u64>().map_err(|_| ())?);
    }
    let mut out = format!("{}.{}.{}", nums[0], nums[1], nums[2]);
    if let Some(pre) = pre_part {
        if pre.is_empty() { return Err(()); }
        let mut parts: Vec<String> = Vec::new();
        for id in pre.split('.') {
            if id.is_empty() || !id.chars().all(|ch| ch.is_ascii_alphanumeric() || ch == '-') { return Err(()); }
            if id.chars().all(|ch| ch.is_ascii_digit()) {
                parts.push(format!("{}", id.parse::<u64>().map_err(|_| ())?));
            } else { parts.push(id.to_string()); }
        }
        out.push('-'); out.push_str(&parts.join("."));
    }
    if let Some(build) = build_part {
        if build.is_empty() { return Err(()); }
        for id in build.split('.') {
            if id.is_empty() || !id.chars().all(|ch| ch.is_ascii_alphanumeric() || ch == '-') { return Err(()); }
        }
        out.push('+'); out.push_str(build);
    }
    Ok(out)
}

fn deserialize_js_version<'de, D: Deserializer<'de>>(d: D) -> Result<Option<String>, D::Error> {
    // Custom visitor expecting "a version string"
    struct V;
    impl<'de> Visitor<'de> for V {
        type Value = Option<String>;
        fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result { write!(f, "a version string") }
        fn visit_str<E: serde::de::Error>(self, s: &str) -> Result<Self::Value, E> {
            match parse_js_version(s) { Ok(v) => Ok(Some(v)), Err(_) => Err(E::custom("Failed to parse version.")) }
        }
        fn visit_string<E: serde::de::Error>(self, s: String) -> Result<Self::Value, E> { self.visit_str(&s) }
        fn visit_none<E: serde::de::Error>(self) -> Result<Self::Value, E> { Ok(None) }
        fn visit_unit<E: serde::de::Error>(self) -> Result<Self::Value, E> { Ok(None) }
        fn visit_some<D2: Deserializer<'de>>(self, d2: D2) -> Result<Self::Value, D2::Error> {
            // This won't be used as we use deserialize_any below?
            let s = String::deserialize(d2)?;
            match parse_js_version(&s) { Ok(v) => Ok(Some(v)), Err(_) => Err(serde::de::Error::custom("Failed to parse version.")) }
        }
    }
    // deserialize_any will call visit_str for strings, visit_i64 etc for others giving invalid type with expecting message
    d.deserialize_any(V)
}

