fn transform_repo_string(s: &str) -> Option<String> {
    // hosted-git-info shortcut/url handling
    // strip committish fragment for shortcut form
    let (before_hash, _frag) = match s.split_once('#') { Some((a, _)) => (a, ()), None => (s, ()) };
    let s_nofrag = before_hash;
    if s_nofrag.contains("://") {
        let (scheme, rest) = s_nofrag.split_once("://")?;
        let allowed = ["git", "git+ssh", "git+https", "git+http"];
        if !allowed.contains(&scheme) { return None; }
        // parse with url crate after converting scheme to https for parsing host/path
        let as_https = format!("https://{}", rest);
        let u = url::Url::parse(&as_https).ok()?;
        let host = u.host_str()?;
        let path = u.path().trim_matches('/');
        if path.is_empty() { return None; }
        let mut out = format!("https://{}/{}", host, path);
        if !out.ends_with(".git") { out.push_str(".git"); }
        return Some(out);
    }
    // shortcut: [platform:]user/project...
    if s_nofrag.contains('@') || s_nofrag.starts_with('/') { return None; }
    let (platform, remainder) = if let Some((p, r)) = s_nofrag.split_once(':') {
        (p, r)
    } else { ("github", s_nofrag) };
    if !["github", "gitlab", "bitbucket", "gist"].contains(&platform) { return None; }
    // remainder must contain a '/'
    let first_slash = remainder.find('/')?;
    let user = &remainder[..first_slash];
    let projpath = &remainder[first_slash + 1..];
    // validation similar to hosted-git-info: user non-empty and no odd chars
    if user.is_empty() || projpath.is_empty() { return None; }
    if !user.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_' || c == '.') { return None; }
    // projpath can contain slashes - hosted-git regex requires at least one char after slash, no spaces
    if projpath.contains(char::is_whitespace) { return None; }
    match platform {
        "github" => Some(format!("https://github.com/{}.git", remainder)),
        "gitlab" => Some(format!("https://gitlab.com/{}.git", remainder)),
        "bitbucket" => Some(format!("https://bitbucket.com/{}.git", remainder)),
        "gist" => Some(format!("https://gist.github.com/{}.git", projpath)),
        _ => None,
    }
}

enum JsErrorKind {
    Diag(Diag, Vec<String>), // inner diag + extra causes flattened
}

fn detect_js(cwd: &Path) -> Option<Result<ProjectInfo, Diag>> {
    let manifest_path = cwd.join("package.json");
    if !manifest_path.is_file() { return None; }
    let manifest_abs = manifest_path.display().to_string();
    let contents = match std::fs::read_to_string(&manifest_path) {
        Ok(c) => c,
        Err(e) => {
            let inner = crate::config::read_asset_diag(&manifest_abs, &e);
            // inner for asset errors: message from inner is already "failed to read asset from ..." with help, and its cause is io error as extra flattened cause.
            // Construct warning: inner diag without its cause, extra causes = [io error]
            let mut inner2 = inner.clone();
            let extra: Vec<String> = inner2.causes.iter().filter_map(|c| if let Cause::Text(t) = c { Some(t.clone()) } else { None }).collect();
            inner2.causes.clear();
            return Some(Err(warning_diag("javascript", &manifest_abs, inner2, extra)));
        }
    };
    let manifest: Manifest = match serde_json::from_str(&contents) {
        Ok(m) => m,
        Err(e) => {
            // failed to parse JSON diag with filename absolute
            let mut inner = parse_json_diag(&contents, &manifest_abs, &e);
            // move its cause to extra
            let extra: Vec<String> = inner.causes.iter().filter_map(|c| if let Cause::Text(t) = c { Some(t.clone()) } else { None }).collect();
            inner.causes.clear();
            return Some(Err(warning_diag("javascript", &manifest_abs, inner, extra)));
        }
    };
    if manifest.name.is_none() {
        let inner = Diag::error(format!("your package doesn't have a name: {}", manifest_abs)).with_help("is it a workspace? We don't support that yet.");
        return Some(Err(warning_diag("javascript", &manifest_abs, inner, vec![])));
    }
    // binaries reparse
    let reparse: BinReparse = match serde_json::from_str(&contents) {
        Ok(v) => v,
        Err(e) => {
            let inner = Diag::error(format!("Failed to read the binaries from your package.json: {}", manifest_abs));
            return Some(Err(warning_diag("javascript", &manifest_abs, inner, vec![format!("{}", e)])));
        }
    };
    // binaries list (currently not used except to cause IO errors for directories.bin when bin is None)
    if manifest.bin.is_none() {
        if let Some(dirs) = &reparse.directories {
            if let Some(bin_path) = &dirs.bin {
                let p = &bin_path.0;
                let path_obj = Path::new(p);
                // If it is a file (following), fine. Else attempt read_dir.
                if !path_obj.is_file() {
                    // read_dir on the raw path (relative to cwd)
                    match std::fs::read_dir(path_obj) {
                        Ok(mut it) => {
                            // consume? iterate - errors on iteration use fs-err style too - simplified: try collect
                            if let Err(e) = it.try_for_each(|_| Ok::<(), std::io::Error>(())) {
                                let _ = e;
                            }
                        }
                        Err(e) => {
                            let inner = Diag::error(format!("Failed to read the binaries from your package.json: {}", manifest_abs));
                            let first = format!("IO error for operation on {}: {}", p, e);
                            let second = format!("{}", e);
                            return Some(Err(warning_diag("javascript", &manifest_abs, inner, vec![first, second])));
                        }
                    }
                }
            }
        }
    }
    let repository = match &manifest.repository {
        Some(Repository::Shortcut(s)) => transform_repo_string(s),
        Some(Repository::Info(info)) => info.url.clone(),
        None => None,
    };
    let readme_path = find_readme(cwd);
    Some(Ok(ProjectInfo {
        name: manifest.name.clone(),
        version: manifest.version.clone(),
        description: manifest.description.clone(),
        homepage: manifest.homepage.clone(),
        repository,
        license: manifest.license.clone(),
        readme_path,
        cargo_dist_detected: false,
    }))
}

pub fn detect_project(cwd: &Path) -> (ProjectInfo, bool) {
    let mut chosen: Option<ProjectInfo> = None;
    if let Some(res) = detect_rust(cwd) {
        match res {
            Ok(p) => { chosen = Some(p); }
            Err(w) => { eprint_diag(&w); }
        }
    }
    if let Some(res) = detect_js(cwd) {
        match res {
            Ok(p) => {
                if chosen.is_some() {
                    log_warn(&format!("Also found a Javascript project at {}, but we're ignoring it", abs_string(cwd, "package.json")));
                } else {
                    chosen = Some(p);
                }
            }
            Err(w) => { eprint_diag(&w); }
        }
    }
    let proj = chosen.unwrap_or(ProjectInfo { name: None, version: None, description: None, homepage: None, repository: None, license: None, readme_path: None, cargo_dist_detected: false });
    let cd = proj.cargo_dist_detected;
    (proj, cd)
}
