use crate::diag::*;
use std::io::{Read, Write};
use std::process::{Command, Stdio};
use std::net::ToSocketAddrs;

#[derive(Clone, Debug)]
pub struct FetchError {
    pub message: String,
    pub causes: Vec<String>,
}
impl FetchError {
    pub fn full_causes(&self) -> Vec<String> {
        let mut v = vec![self.message.clone()];
        v.extend(self.causes.clone());
        v
    }
    pub fn to_diag(&self) -> Diag { Diag::error(self.message.clone()).with_causes(self.causes.clone()) }
}

fn dns_error(url: &str, io_msg: &str) -> FetchError {
    let c1 = format!("error trying to connect: dns error: {}", io_msg);
    let c2 = format!("dns error: {}", io_msg);
    FetchError { message: format!("error sending request for url ({}): {}", url, c1), causes: vec![c1, c2, io_msg.to_string()] }
}
fn tunnel_error(url: &str) -> FetchError {
    let c1 = "error trying to connect: unsuccessful tunnel".to_string();
    FetchError { message: format!("error sending request for url ({}): {}", url, c1), causes: vec![c1, "unsuccessful tunnel".to_string()] }
}
fn tls_error(url: &str) -> FetchError {
    let c1 = "error trying to connect: invalid peer certificate: UnknownIssuer".to_string();
    FetchError { message: format!("error sending request for url ({}): {}", url, c1), causes: vec![c1, "invalid peer certificate: UnknownIssuer".to_string()] }
}
fn connect_error(url: &str, io_msg: &str) -> FetchError {
    // reqwest connect errors for tcp failures: "error trying to connect: {io}"? with io as its source
    let c1 = format!("error trying to connect: {}", io_msg);
    FetchError { message: format!("error sending request for url ({}): {}", url, c1), causes: vec![c1, io_msg.to_string()] }
}

fn proxy_for_url(url_str: &str) -> Option<String> {
    let u = url::Url::parse(url_str).ok()?;
    let host = u.host_str().unwrap_or("").to_lowercase();
    // NO_PROXY check (simple)
    for key in ["NO_PROXY", "no_proxy"] {
        if let Ok(v) = std::env::var(key) {
            for pat in v.split(',') {
                let pat = pat.trim().to_lowercase();
                if pat.is_empty() { continue; }
                if pat == "*" { return None; }
                let pat = pat.strip_prefix('.').unwrap_or(&pat);
                if host == pat || host.ends_with(&format!(".{}", pat)) { return None; }
            }
        }
    }
    let scheme = u.scheme();
    let keys: Vec<String> = if scheme == "https" {
        vec!["HTTPS_PROXY".into(), "https_proxy".into(), "ALL_PROXY".into(), "all_proxy".into()]
    } else {
        vec!["HTTP_PROXY".into(), "http_proxy".into(), "ALL_PROXY".into(), "all_proxy".into()]
    };
    for k in keys {
        if let Ok(v) = std::env::var(&k) {
            if !v.is_empty() { return Some(v); }
        }
    }
    None
}

fn parse_host_port(authority: &str, default_port: u16) -> Option<(String, u16)> {
    // strip userinfo
    let a = match authority.rsplit_once('@') { Some((_, rest)) => rest, None => authority };
    if let Some(rest) = a.strip_prefix('[') {
        let (h, rest) = rest.split_once(']')?;
        let port = rest.strip_prefix(':').and_then(|p| p.parse().ok()).unwrap_or(default_port);
        return Some((h.to_string(), port));
    }
    if let Some((h, p)) = a.rsplit_once(':') {
        if let Ok(port) = p.parse::<u16>() { return Some((h.to_string(), port)); }
    }
    Some((a.to_string(), default_port))
}

fn proxy_preflight(proxy: &str, target_url: &str) -> Result<(), FetchError> {
    // Only http proxies via CONNECT for https targets
    let target = url::Url::parse(target_url).map_err(|_| connect_error(target_url, "invalid url"))?;
    if target.scheme() != "https" { return Ok(()); }
    let proxy_url_str = if proxy.contains("://") { proxy.to_string() } else { format!("http://{}", proxy) };
    let pu = url::Url::parse(&proxy_url_str).map_err(|_| tunnel_error(target_url))?;
    let phost = pu.host_str().unwrap_or("").to_string();
    let pport = pu.port().unwrap_or(80);
    // resolve proxy
    let addr_str = format!("{}:{}", phost, pport);
    let mut addrs = match addr_str.to_socket_addrs() {
        Ok(a) => a,
        Err(e) => {
            // reqwest: dns error for proxy host resolution looks same shape as dns error against target url
            return Err(dns_error(target_url, &format!("{}", e)));
        }
    };
    let Some(addr) = addrs.next() else { return Err(dns_error(target_url, "failed to lookup address information: No address")); };
    let mut stream = match std::net::TcpStream::connect_timeout(&addr, std::time::Duration::from_secs(10)) {
        Ok(s) => s,
        Err(e) => {
            return Err(connect_error(target_url, &format!("{}", e)));
        }
    };
    let thost = target.host_str().unwrap_or("");
    let tport = target.port().unwrap_or(443);
    let req = format!("CONNECT {}:{} HTTP/1.1\r\nHost: {}:{}\r\n\r\n", thost, tport, thost, tport);
    if stream.write_all(req.as_bytes()).is_err() { return Err(tunnel_error(target_url)); }
    // read status line
    let _ = stream.set_read_timeout(Some(std::time::Duration::from_secs(10)));
    let mut buf = [0u8; 1024];
    let n = match stream.read(&mut buf) { Ok(n) => n, Err(_) => return Err(tunnel_error(target_url)) };
    let resp = String::from_utf8_lossy(&buf[..n]).to_string();
    let status_ok = resp.starts_with("HTTP/1.1 200") || resp.starts_with("HTTP/1.0 200");
    if !status_ok { return Err(tunnel_error(target_url)); }
    Ok(())
}

fn run_curl(url: &str) -> Option<(i32, Vec<u8>, String, Option<u16>)> {
    // Use curl if present; capture body, status via -w
    let out = Command::new("curl")
        .args(["-L", "-s", "-S", "--max-time", "30", "-o", "-", "-w", "\n__ORANDA_HTTP_STATUS__:%{http_code}", url])
        .stdout(Stdio::piped()).stderr(Stdio::piped())
        .output().ok()?;
    let code = out.status.code().unwrap_or(-1);
    let mut body = out.stdout.clone();
    let mut status: Option<u16> = None;
    if let Some(pos) = body.windows(25).rposition(|w| w == b"\n__ORANDA_HTTP_STATUS__:") {
        // marker is 24? compute properly below by string search
        let _ = pos;
    }
    // string search marker at end
    let marker = b"\n__ORANDA_HTTP_STATUS__:";
    if let Some(idx) = body.windows(marker.len()).rposition(|w| w == marker) {
        let code_bytes = &body[idx + marker.len()..];
        if let Ok(cs) = std::str::from_utf8(code_bytes) {
            status = cs.trim().parse::<u16>().ok();
        }
        body.truncate(idx);
    }
    Some((code, body, String::from_utf8_lossy(&out.stderr).to_string(), status))
}

fn run_wget(url: &str) -> Option<(i32, Vec<u8>, String, Option<u16>)> {
    let out = Command::new("wget").args(["-q", "-O", "-", url]).stdout(Stdio::piped()).stderr(Stdio::piped()).output().ok()?;
