    Some((out.status.code().unwrap_or(-1), out.stdout, String::from_utf8_lossy(&out.stderr).to_string(), None))
}

pub fn fetch_bytes(url: &str) -> Result<Vec<u8>, FetchError> {
    let parsed = url::Url::parse(url).map_err(|e| FetchError { message: format!("error sending request for url ({}): {}", url, e), causes: vec![] })?;
    let host = parsed.host_str().unwrap_or("").to_string();
    let is_https = parsed.scheme() == "https";
    let proxy = proxy_for_url(url);
    if let Some(px) = &proxy {
        proxy_preflight(px, url)?;
    } else if is_https || parsed.scheme() == "http" {
        // DNS preflight using ToSocketAddrs with port
        let port = parsed.port().unwrap_or(if is_https { 443 } else { 80 });
        // If host is an IP, ToSocketAddrs succeeds without DNS
        let addr_str = if host.contains(':') { format!("[{}]:{}", host, port) } else { format!("{}:{}", host, port) };
        match addr_str.to_socket_addrs() {
            Err(e) => {
                // e is io error - for dns failures its display is "failed to lookup address information: ..."
                let msg = format!("{}", e);
                if msg.contains("failed to lookup") || msg.contains("Name or service") || msg.contains("Temporary failure") {
                    return Err(dns_error(url, &msg));
                } else {
                    // might be invalid input etc - treat as dns
                    return Err(dns_error(url, &msg));
                }
            }
            Ok(mut it) => { if it.next().is_none() { return Err(dns_error(url, "failed to lookup address information: No address")); } }
        }
    }
    // attempt curl then wget
    if let Some((code, body, stderr, status)) = run_curl(url) {
        if code == 0 {
            if let Some(st) = status {
                if st >= 400 {
                    let reason = match st { 400=>"Bad Request",401=>"Unauthorized",403=>"Forbidden",404=>"Not Found",405=>"Method Not Allowed",500=>"Internal Server Error",502=>"Bad Gateway",503=>"Service Unavailable", _=>"" };
                    let kind = if st < 500 { "client" } else { "server" };
                    let msg = if reason.is_empty() { format!("HTTP status {} error ({}) for url ({})", kind, st, url) } else { format!("HTTP status {} error ({} {}) for url ({})", kind, st, reason, url) };
                    return Err(FetchError { message: msg, causes: vec![] });
                }
            }
            return Ok(body);
        }
        // map curl codes
        return Err(match code {
            5 | 6 => {
                // resolve failed - recreate dns error by trying resolution of relevant host
                let h = if proxy.is_some() { proxy.clone().unwrap_or(host.clone()) } else { format!("{}:443", host) };
                let _ = h;
                // use generic message from stderr? try resolve target host for message
                let addr_str = format!("{}:443", host);
                if let Err(e) = addr_str.to_socket_addrs() { dns_error(url, &format!("{}", e)) } else { dns_error(url, "failed to lookup address information: Name or service not known") }
            }
            7 => {
                // connection refused etc - attempt tcp connect to get io msg
                let port = parsed.port().unwrap_or(if is_https {443} else {80});
                let addr_str = format!("{}:{}", host, port);
                let mut msg = "Connection refused (os error 111)".to_string();
                if let Ok(mut addrs) = addr_str.to_socket_addrs() { if let Some(a) = addrs.next() { if let Err(e) = std::net::TcpStream::connect_timeout(&a, std::time::Duration::from_secs(3)) { msg = format!("{}", e); } } }
                connect_error(url, &msg)
            }
            35 | 60 | 51 | 58 | 59 | 83 | 90 | 91 => tls_error(url),
            22 => {
                let st = status.unwrap_or(404);
                let reason = match st { 404=>"Not Found",403=>"Forbidden",401=>"Unauthorized", _=>"" };
                let kind = if st < 500 { "client" } else { "server" };
                FetchError { message: format!("HTTP status {} error ({} {}) for url ({})", kind, st, reason, url), causes: vec![] }
            }
            _ => {
                let first = stderr.lines().next().unwrap_or("").trim().to_string();
                if first.contains("SSL") || first.contains("certificate") { tls_error(url) } else if first.is_empty() { connect_error(url, "error trying to connect") } else { FetchError { message: format!("error sending request for url ({}): {}", url, first), causes: vec![first] } }
            }
        });
    }
    if let Some((code, body, _stderr, _)) = run_wget(url) {
        if code == 0 { return Ok(body); }
    }
    Err(connect_error(url, "error trying to connect"))
}

pub fn fetch_with_fallback(proxy_url: &str, direct_url: &str) -> Result<Vec<u8>, FetchError> {
    match fetch_bytes(proxy_url) {
        Ok(b) => Ok(b),
        Err(e) => {
            println!("Fetching from proxy encountered an error:\n {}.\n Falling back to GitHub directly...", e.message);
            use std::io::Write; let _ = std::io::stdout().flush();
            fetch_bytes(direct_url)
        }
    }
}
