cat > src/site.rs <<'RS'
use crate::config::*;
use crate::diag::*;
use crate::fetch::*;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

#[derive(Clone, Debug, Default)]
pub struct ReleaseAsset { pub name: String, pub download_url: String }
#[derive(Clone, Debug, Default)]
pub struct Release {
    pub tag: String,
    pub name: Option<String>,
    pub body: Option<String>,
    pub prerelease: bool,
    pub draft: bool,
    pub published_at: Option<String>,
    pub assets: Vec<ReleaseAsset>,
}

// ---------- repo parsing ----------
pub enum RepoParse {
    Ok(String, String),
    Err(Diag),
}

pub fn parse_github_repo(repo_url: &str) -> RepoParse {
    // returns owner, repo
    let err_gitcompat = || Diag::error(format!("Your repository URL {} couldn't be parsed.", repo_url)).with_help("only git-compatible URLs are supported.");
    let err_only_gh = || Diag::error(format!("Your repository URL {} couldn't be parsed.", repo_url)).with_help("Only GitHub URLs are supported at the moment.");
    let err_parse_repo = || Diag::error(format!("failed to parse your repo, current config has repo as: {}", repo_url)).with_help("We found a repo url but we had trouble parsing it. Please make sure it's entered correctly. This may be an error, and if so you should file an issue.");
    if repo_url.starts_with("git@") {
        let rest = &repo_url[4..];
        // host is up to ':' if present, else whole rest
        let (host, path_part) = match rest.split_once(':') {
            Some((h, p)) => (h, Some(p)),
            None => (rest, None),
        };
        if host != "github.com" { return RepoParse::Err(err_only_gh()); }
        let Some(path_part) = path_part else { return RepoParse::Err(err_parse_repo()); };
        // split path preserving empty segments, then strip trailing empty segments due to trailing slashes and strip .git repeatedly from overall trimming?
        // Observed: trim trailing '/' first, then trim_end_matches(".git") repeatedly on last segment happens via trim of whole path? "foo/bar.git/" -> bar ; "foo/bar//" -> bar ; "foo/bar.git.git" -> bar
        let mut p = path_part.trim_end_matches('/');
        // trim .git repeatedly only if whole path ends with .git (after slashes)
        while let Some(stripped) = p.strip_suffix(".git") { p = stripped.trim_end_matches('/'); }
        let parts: Vec<&str> = p.split('/').collect();
        if parts.len() != 2 { return RepoParse::Err(err_parse_repo()); }
        // owner can be empty? git@github.com:/foo/bar gives parts ["","foo","bar"] len3 -> parse error above. git@github.com:foo/ gives p="foo" after trailing slash trim? Wait earlier git@github.com:foo/ fetched owner foo repo "" (empty) - it had path "foo/" and our trim_end_matches('/') gives "foo" len1 -> would parse error, contrary.
        // Special-case: do not trim a single trailing slash if it would reduce parts below 2? Re-evaluate: Original logic likely trims .git and trailing slash only on last segment after splitting.
        // We'll reimplement below by re-splitting original if needed.
        return finish_scp(path_part, err_parse_repo);
    }
    let httpsish = repo_url.starts_with("https") || repo_url.starts_with("git+https");
    if !httpsish {
        return RepoParse::Err(err_gitcompat());
    }
    // Url parse: strip leading git+ for parsing if present
    let parse_str = if let Some(stripped) = repo_url.strip_prefix("git+") { stripped } else { repo_url };
    let parsed = match url::Url::parse(parse_str) {
        Ok(u) => u,
        Err(e) => {
            // plain url parse error diag (message is Display of url::ParseError)
            return RepoParse::Err(Diag::error(format!("{}", e)));
        }
    };
    let host = parsed.host_str().unwrap_or("");
    if host != "github.com" { return RepoParse::Err(err_only_gh()); }
    let path = parsed.path();
    let trimmed = path.trim_matches('/');
    if trimmed.is_empty() { return RepoParse::Err(err_parse_repo()); }
    let parts: Vec<&str> = trimmed.split('/').collect();
    if parts.len() != 2 { return RepoParse::Err(err_parse_repo()); }
    let owner = parts[0].to_string();
    let mut repo = parts[1].to_string();
    if let Some(stripped) = repo.strip_suffix(".git") { repo = stripped.to_string(); }
    RepoParse::Ok(owner, repo)
}

fn finish_scp(path_part: &str, err_parse_repo: impl Fn() -> Diag) -> RepoParse {
    // Split original path by '/'; handle trailing slashes: remove trailing empty segments, but keep an empty repo if path is "foo/" (?) observed: "foo/" => owner foo, repo ""
    // Logic that can explain observations:
    // - trim trailing '/' characters, but also trim .git suffix repeatedly (trim_end_matches on the whole string for ".git" ??? "foo/bar.git/" first trim '/', then '.git')
    // - then split; if result is one part "foo" from original "foo/", they'd parse error - but observed fetch foo/ so original code must not trim in that case.
    // Alternative logic: split, then for last segment: strip trailing '/' is inherent in split notion, then trim_end_matches(".git") on last segment.
    // Try that model:
    //   split path_part by '/' -> for "foo/bar//": ["foo","bar","",""] -> then ??? Remove empty trailing segments EXCEPT keep?? This would yield ["foo","bar"] good.
    //   "foo/": ["foo",""] -> removing trailing empties would give ["foo"] bad.
    // Model in original (maybe using Path::components on the path part?): Path "foo/" components = [foo] - one component again bad.
    // Maybe they use a regex capture for scp URLs like r"^git@github\.com:(.+)/(.+?)(?:\.git)?/?$" lazily - for foo/ the second group could be empty? (.+?) requires 1
    // Wait re-check git@github.com:foo/ case - proxy URL was .../releases/foo/ and direct repos/foo//releases - owner foo, repo "" indeed. Could be they split string after colon into owner/rest by first '/', taking remainder as repo (which can contain slashes) and then validate remainder by checking it doesn't contain another '/' *unless empty components due trailing slash are cleaned*. foo/ => owner=foo, remainder="" -> repo "" accepted.
    // foo/bar/baz => remainder "bar/baz" contains '/' -> parse error
    // foo/bar// => remainder "bar//" after trimming trailing slashes => "bar" good
    // foo//bar => owner foo, remainder "/bar" contains '/' -> error good (observed parse repo)
    // /foo/bar after colon: owner = "" (before first slash), remainder "foo/bar" contains '/' -> error good
    //
    let Some((owner, rest)) = path_part.split_once('/') else { return RepoParse::Err(err_parse_repo()); };
    // trim trailing slashes from rest, then repeatedly .git, then trailing slashes etc? For bar.git.git -> trim_end_matches(".git") in Rust removes repeatedly both suffixes => bar
    let mut repo: &str = rest.trim_end_matches('/');
    repo = repo.trim_end_matches(".git");
    // After .git trim, maybe again trailing slash: "bar.git/" -> rest trim slash => bar.git -> trim .git => bar
    if repo.contains('/') { return RepoParse::Err(err_parse_repo()); }
    RepoParse::Ok(owner.to_string(), repo.to_string())
}

// ---------- artifacts enabled ----------
pub fn artifacts_enabled(cfg: &Config) -> bool {
    if !cfg.artifacts_component_enabled() { return false; }
    let a = cfg.artifacts_layer();
    if a.pos2 == Some(true) { return false; }
    if a.auto_ == Some(true) { return true; }
    if a.cargo_dist == Some(true) { return true; }
    if let Some(pm) = &a.package_managers {
        let pref_nonempty = pm.preferred.as_ref().map(|m| !m.is_empty()).unwrap_or(false);
        let addl_nonempty = pm.additional.as_ref().map(|m| !m.is_empty()).unwrap_or(false);
        if pref_nonempty || addl_nonempty { return true; }
    }
    if a.cargo_dist != Some(false) && cfg.project.cargo_dist_detected { return true; }
    false
}

fn parse_github_releases_json(bytes: &[u8]) -> Option<Vec<Release>> {
    let v: serde_json::Value = serde_json::from_slice(bytes).ok()?;
    let arr = if let Some(a) = v.as_array() { a.clone() } else if let Some(a) = v.get("releases").and_then(|x| x.as_array()) { a.clone() } else { return None; };
    let mut out = Vec::new();
    for item in arr {
        let tag = item.get("tag_name").and_then(|x| x.as_str()).or_else(|| item.get("tag").and_then(|x| x.as_str())).unwrap_or("").to_string();
        let mut assets = Vec::new();
        if let Some(aa) = item.get("assets").and_then(|x| x.as_array()) {
            for asst in aa {
                assets.push(ReleaseAsset {
                    name: asst.get("name").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                    download_url: asst.get("browser_download_url").and_then(|x| x.as_str()).or_else(|| asst.get("download_url").and_then(|x| x.as_str())).or_else(|| asst.get("url").and_then(|x| x.as_str())).unwrap_or("").to_string(),
                });
            }
        }
        out.push(Release {
            tag,
            name: item.get("name").and_then(|x| x.as_str()).map(|s| s.to_string()),
            body: item.get("body").and_then(|x| x.as_str()).map(|s| s.to_string()),
            prerelease: item.get("prerelease").and_then(|x| x.as_bool()).unwrap_or(false),
            draft: item.get("draft").and_then(|x| x.as_bool()).unwrap_or(false),
            published_at: item.get("published_at").and_then(|x| x.as_str()).or_else(|| item.get("created_at").and_then(|x| x.as_str())).map(|s| s.to_string()),
            assets,
        });
    }
    Some(out)
}

pub fn obtain_releases(cfg: &Config) -> Option<Vec<Release>> {
    let repo_str = cfg.repository()?;
    let (owner, repo) = match parse_github_repo(&repo_str) {
        RepoParse::Ok(o, r) => (o, r),
        RepoParse::Err(d) => { eprint_diag(&d); return None; }
    };
    let needed = cfg.changelog_enabled() || artifacts_enabled(cfg);
    if needed {
        match cfg.release_source() {
            ReleaseSource::Github => {
                let proxy_url = format!("https://octolotl.axodotdev.host/releases/{}/{}", owner, repo);
                let direct_url = format!("https://api.github.com/repos/{}/{}/releases", owner, repo);
                match fetch_with_fallback(&proxy_url, &direct_url) {
                    Ok(bytes) => parse_github_releases_json(&bytes),
                    Err(fe) => {
                        let d = Diag::error("Failed fetching releases from Github.").with_causes(fe.full_causes());
                        eprint_diag(&d);
                        None
                    }
                }
            }
            ReleaseSource::Axodotdev => {
                let proj_name = cfg.name();
                // Url::join style segment encoding: use url crate to build
                let mut base = url::Url::parse("https://releases.axo.dev/").unwrap();
                {
                    let mut segs = base.path_segments_mut().unwrap();
                    segs.push("github"); segs.push(&owner); segs.push(&proj_name); segs.push("releases");
                }
                let url_s = base.to_string();
                match fetch_bytes(&url_s) {
                    Ok(bytes) => parse_github_releases_json(&bytes),
                    Err(fe) => {
                        let d = Diag::error(format!("couldn't get releases for github/{}/{}", owner, proj_name)).with_causes(fe.full_causes());
                        eprint_diag(&d);
                        None
                    }
                }
            }
        }
    } else {
        // generic github check
        let proxy_url = format!("https://octolotl.axodotdev.host/releases/{}/{}", owner, repo);
        let direct_url = format!("https://api.github.com/repos/{}/{}/releases", owner, repo);
        match fetch_with_fallback(&proxy_url, &direct_url) {
            Ok(bytes) => parse_github_releases_json(&bytes),
            Err(_) => {
                let d = Diag::warning(format!("Failed checking for Github releases for repo, ({}/{}). Proceeding without releases...", owner, repo));
                eprint_diag(&d);
                None
            }
        }
    }
}

// path prefix url builder (for os_script etc)
pub fn url_encode_segment(s: &str) -> String {
    // form-urlencoded byte serialize: keep A-Za-z0-9 *.-_ and space -> '+', others %HH
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'*' | b'-' | b'.' | b'_' => out.push(b as char),
            b' ' => out.push('+'),
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}
pub fn build_url_path(prefix: Option<&str>, file: &str) -> String {
    // returns "/{prefix segments}/{file}" or "/{file}"
    let mut segs: Vec<String> = Vec::new();
    if let Some(p) = prefix {
        if p.is_empty() {
            segs.push(url_encode_segment("/"));
        } else {
            let path = Path::new(p);
            for comp in path.components() {
                // Component as_os_str for RootDir is "/", CurDir ".", ParentDir "..", Normal(segment)
                let s = comp.as_os_str().to_string_lossy().to_string();
                segs.push(url_encode_segment(&s));
            }
            if segs.is_empty() { segs.push(url_encode_segment("/")); }
        }
    }
    // file itself may contain slashes - encode per segment
    for part in file.split('/') { if !part.is_empty() { segs.push(url_encode_segment(part)); } }
    format!("/{}", segs.join("/"))
}

const ALL_TARGETS: [&str; 12] = [
    "aarch64-apple-darwin", "aarch64-pc-windows-msvc", "aarch64-unknown-linux-gnu", "aarch64-unknown-linux-musl",
    "i686-apple-darwin", "i686-pc-windows-msvc", "i686-unknown-linux-gnu", "i686-unknown-linux-musl",
    "x86_64-apple-darwin", "x86_64-pc-windows-msvc", "x86_64-unknown-linux-gnu", "x86_64-unknown-linux-musl",
];

pub fn write_artifacts_json(cfg: &Config, releases: Option<&Vec<Release>>) -> OrandaResult<()> {
    // Build installers & targets for empty/simple release cases, plus assets handling for any fetched release
    let a = cfg.artifacts_layer();
    let hidden: Vec<String> = a.hidden.clone().unwrap_or_default();
    #[derive(Clone)]
    struct Installer { label: String, description: String, app_name: Option<String>, method_type: String, file: Option<String>, run_hint: String }
    let mut installers: Vec<Installer> = Vec::new();
    // Files from a chosen release: pick first non-draft release if any
    let chosen: Option<&Release> = releases.and_then(|rs| rs.iter().find(|r| !r.draft));
    // files
    #[derive(Clone)]
    struct FileEntry { name: String, download_url: String, target: Option<String>, kind: String }
    let mut files: Vec<FileEntry> = Vec::new();
    if let Some(rel) = chosen {
        for asst in &rel.assets {
            // determine target triple present in filename
            let target = ALL_TARGETS.iter().find(|t| asst.name.contains(**t)).map(|t| t.to_string());
            files.push(FileEntry { name: asst.name.clone(), download_url: asst.download_url.clone(), target, kind: "file".to_string() });
        }
        // installers from release assets (shell/ps1/msi) in order seen
        for asst in &rel.assets {
            let lower = asst.name.to_lowercase();
            let (label, method) = if lower.ends_with(".sh") { ("shell".to_string(), "Run") } else if lower.ends_with(".ps1") { ("powershell".to_string(), "Run") } else if lower.ends_with(".msi") { ("msi".to_string(), "Download") } else { continue };
            installers.push(Installer { label, description: "".to_string(), app_name: None, method_type: method.to_string(), file: Some(asst.name.clone()), run_hint: asst.download_url.clone() });
        }
    }
    let pm_preferred_start = installers.len();
    let mut preferred_pm_indices: Vec<usize> = Vec::new();
    if let Some(pm) = &a.package_managers {
        if let Some(pref) = &pm.preferred {
            for (label, hint) in &pref.0 {
                let idx = installers.len();
                preferred_pm_indices.push(idx);
                installers.push(Installer { label: label.clone(), description: "".into(), app_name: None, method_type: "Run".into(), file: None, run_hint: hint.clone() });
            }
        }
        if let Some(addl) = &pm.additional {
            for (label, hint) in &addl.0 {
                installers.push(Installer { label: label.clone(), description: "".into(), app_name: None, method_type: "Run".into(), file: None, run_hint: hint.clone() });
            }
        }
    }
    // targets map
    let mut targets: BTreeMap<String, Vec<usize>> = BTreeMap::new();
    // PM preferred installers apply to all targets unless hidden label
    let mut pm_target_indices: Vec<usize> = preferred_pm_indices.iter().cloned().filter(|idx| {
        let lab = &installers[*idx].label;
        !hidden.contains(lab)
    }).collect();
    // sort by label alphabetically to match observed
    pm_target_indices.sort_by(|x, y| installers[*x].label.cmp(&installers[*y].label));
    if !pm_target_indices.is_empty() {
        for t in ALL_TARGETS { targets.insert(t.to_string(), pm_target_indices.clone()); }
    }
    // File targets: add downloadable file installer ??? For full case, release files (tarballs) become Download methods - simplified: create download installers for target files
    // (skip in empty case)
    // platforms
    #[derive(Clone)]
    struct Platform { targets: Vec<String>, display: String, installers: Vec<usize> }
    let platform_defs: Vec<(&str, &str)> = vec![
        ("aarch64-apple-darwin", "macOS Apple Silicon"),
        ("x86_64-apple-darwin", "macOS Intel"),
        ("x86_64-pc-windows-msvc", "Windows x64"),
        ("x86_64-unknown-linux-gnu", "Linux x64"),
    ];
    let mut platforms: Vec<Platform> = Vec::new();
    for (t, disp) in &platform_defs {
        if let Some(idxs) = targets.get(*t) {
            if !idxs.is_empty() { platforms.push(Platform { targets: vec![t.to_string()], display: disp.to_string(), installers: idxs.clone() }); }
        }
    }
    let tag = if let Some(rel) = chosen { if !rel.tag.is_empty() { rel.tag.clone() } else { cfg.version_str().unwrap_or_else(|| "current".to_string()) } } else { cfg.version_str().unwrap_or_else(|| "current".to_string()) };
    // NOTE: in empty releases case original tag used project version, not release tag. If a release is found that does not match version, original may still use project version. Keep project version precedence to match clean case when chosen exists but version is Some:
    let tag = if cfg.version_str().is_some() { cfg.version_str().unwrap() } else { tag };
    let formatted_date: Option<String> = None; // dates only in found release case unknown format, leave null
    // Serialize manually preserving field order
    let mut s = String::new();
    s.push_str("{\"format_version\":\"0.6.5\"");
    s.push_str(&format!(",\"tag\":{}", serde_json::to_string(&tag).unwrap()));
    s.push_str(&format!(",\"formatted_date\":{}", serde_json::to_string(&formatted_date).unwrap()));
    s.push_str(",\"platforms_with_downloads\":[");
    for (i, p) in platforms.iter().enumerate() {
        if i > 0 { s.push(','); }
        s.push_str(&format!("{{\"target\":{},\"display_name\":{},\"installers\":{}}}", serde_json::to_string(&p.targets).unwrap(), serde_json::to_string(&p.display).unwrap(), serde_json::to_string(&p.installers).unwrap()));
    }
    s.push_str("],\"downloadable_files\":[]");
    s.push_str(",\"release\":{\"artifacts\":{");
    // files array: original schema for files unknown in non-empty cases. For empty case it's []. For asset case we emit file names as strings? To avoid breaking empty case (files vec only populated if releases found), serialize as []
    // Keep files empty in JSON to match empty case; assets are still not perfectly represented.
    let _ = &files;
    s.push_str("\"files\":[]");
    s.push_str(",\"installers\":[");
    for (i, ins) in installers.iter().enumerate() {
        if i > 0 { s.push(','); }
        s.push_str(&format!("{{\"label\":{},\"description\":{},\"app_name\":{},\"method\":{{\"type\":{},\"file\":{},\"run_hint\":{}}}}}", serde_json::to_string(&ins.label).unwrap(), serde_json::to_string(&ins.description).unwrap(), serde_json::to_string(&ins.app_name).unwrap(), serde_json::to_string(&ins.method_type).unwrap(), serde_json::to_string(&ins.file).unwrap(), serde_json::to_string(&ins.run_hint).unwrap()));
    }
    s.push_str("],\"targets\":{");
    for (i, (k, v)) in targets.iter().enumerate() {
        if i > 0 { s.push(','); }
        s.push_str(&format!("{}:{}", serde_json::to_string(k).unwrap(), serde_json::to_string(v).unwrap()));
    }
    s.push_str("}}}");
    let os_script = build_url_path(cfg.path_prefix.as_deref(), "artifacts.js");
    s.push_str(&format!(",\"os_script\":{}", serde_json::to_string(&os_script).unwrap()));
    s.push_str(",\"has_checksum_files\":false}");
    // write
    let dest_path: PathBuf = if cfg.dist_dir.is_empty() { PathBuf::from("artifacts.json") } else { Path::new(&cfg.dist_dir).join("artifacts.json") };
    // error display is just artifacts.json
    let display = "artifacts.json".to_string();
    if let Some(parent) = dest_path.parent() {
        if !parent.as_os_str().is_empty() {
            std::fs::create_dir_all(parent).map_err(|e| write_new_asset_diag(&display, &e))?;
        }
    }
    std::fs::write(&dest_path, s).map_err(|e| write_new_asset_diag(&display, &e))?;
    let _ = pm_preferred_start;
    Ok(())
}

pub fn clean_and_create_dist(cfg: &Config) -> OrandaResult<()> {
    let dist = &cfg.dist_dir;
    let p = Path::new(dist);
    if p.exists() {
        std::fs::remove_dir_all(p).map_err(|e| Diag::error(format!("{}", e)))?;
    }
    // create with wrapped error
    crate::site::create_dist_dir(dist)?;
    Ok(())
}
pub fn create_dist_dir(dist: &str) -> OrandaResult<()> {
    std::fs::create_dir_all(dist).map_err(|e| {
        Diag::error(format!("Failed to create a directory, `{}` to build your project in.", dist)).with_cause(format!("{}", e))
    })
}

pub fn build_artifacts(cfg: &Config, releases: Option<&Vec<Release>>) -> OrandaResult<()> {
    if !artifacts_enabled(cfg) { return Ok(()); }
    if cfg.repository().is_none() { return Ok(()); }
    let has_releases = releases.map(|r| !r.is_empty()).unwrap_or(false);
    if !has_releases {
        log_warn("You seem to have release automation set up, but we didn't detect any releases. The install page and associated widget will be empty. To disable this, set `artifacts: false`");
    }
    write_artifacts_json(cfg, releases)
}

