fn write_default_favicon(cfg: &Config) -> OrandaResult<()> {
    if cfg.styles().favicon.is_some() { return Ok(()); }
    let dest: PathBuf = if cfg.dist_dir.is_empty() { PathBuf::from("favicon.ico") } else { Path::new(&cfg.dist_dir).join("favicon.ico") };
