pub fn slugify(s: &str) -> String {
    let mut out = String::new();
    for ch in s.chars() {
        if ch.is_ascii_alphanumeric() { out.push(ch.to_ascii_lowercase()); }
        else if ch == ' ' || ch == '_' || ch == '-' { if !out.ends_with('-') { out.push('-'); } }
    }
    out.trim_matches('-').to_string()
}

fn html_escape(s: &str) -> String { s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;") }

pub fn markdown_to_html(md: &str) -> String {
    // very small markdown converter: headings, paragraphs, lists, fenced code, inline code/bold/links (best effort)
    let mut html = String::new();
    let mut in_code = false;
    let mut in_list = false;
    let mut para: Vec<String> = Vec::new();
    let flush_para = |html: &mut String, para: &mut Vec<String>| {
        if !para.is_empty() {
            html.push_str("<p>"); html.push_str(&inline_md(&para.join(" "))); html.push_str("</p>\n"); para.clear();
        }
    };
    for line in md.lines() {
        if line.starts_with("```") {
            if in_code { html.push_str("</code></pre>\n"); in_code = false; } else { flush_para(&mut html, &mut para); if in_list { html.push_str("</ul>\n"); in_list = false; } html.push_str("<pre><code>"); in_code = true; }
            continue;
        }
        if in_code { html.push_str(&html_escape(line)); html.push('\n'); continue; }
        let trimmed = line.trim();
        if trimmed.is_empty() { flush_para(&mut html, &mut para); if in_list { html.push_str("</ul>\n"); in_list = false; } continue; }
        if let Some(h) = trimmed.strip_prefix("# ") { flush_para(&mut html, &mut para); html.push_str(&format!("<h1>{}</h1>\n", inline_md(h))); continue; }
        if let Some(h) = trimmed.strip_prefix("## ") { flush_para(&mut html, &mut para); html.push_str(&format!("<h2>{}</h2>\n", inline_md(h))); continue; }
        if let Some(h) = trimmed.strip_prefix("### ") { flush_para(&mut html, &mut para); html.push_str(&format!("<h3>{}</h3>\n", inline_md(h))); continue; }
        if let Some(h) = trimmed.strip_prefix("#### ") { flush_para(&mut html, &mut para); html.push_str(&format!("<h4>{}</h4>\n", inline_md(h))); continue; }
        if trimmed.starts_with("- ") || trimmed.starts_with("* ") {
            flush_para(&mut html, &mut para);
            if !in_list { html.push_str("<ul>\n"); in_list = true; }
            html.push_str(&format!("<li>{}</li>\n", inline_md(&trimmed[2..])));
            continue;
        }
        para.push(trimmed.to_string());
    }
    flush_para(&mut html, &mut para);
    if in_list { html.push_str("</ul>\n"); }
    if in_code { html.push_str("</code></pre>\n"); }
    html
}
fn inline_md(s: &str) -> String {
    let mut out = html_escape(s);
    // [text](url)
    out = replace_links(&out);
    // simple **bold**, *italic*, `code`
    out = replace_pair(&out, "**", "<strong>", "</strong>");
    out = replace_pair(&out, "`", "<code>", "</code>");
    out
}
fn replace_pair(s: &str, marker: &str, open: &str, close: &str) -> String {
    let mut out = String::new(); let mut rest = s; let mut inside = false;
    while let Some(idx) = rest.find(marker) {
        out.push_str(&rest[..idx]);
        out.push_str(if inside { close } else { open });
        inside = !inside;
        rest = &rest[idx + marker.len()..];
    }
    out.push_str(rest);
    if inside { out.push_str(close); }
    out
}
fn replace_links(s: &str) -> String {
    let mut out = String::new(); let mut rest = s;
    while let Some(start) = rest.find('[') {
        if let Some(mid_rel) = rest[start..].find("](") {
            let mid = start + mid_rel;
            if let Some(end_rel) = rest[mid..].find(')') {
                let end = mid + end_rel;
                out.push_str(&rest[..start]);
                let text = &rest[start + 1..mid];
                let url = &rest[mid + 2..end];
                out.push_str(&format!("<a href=\"{}\">{}</a>", url, text));
                rest = &rest[end + 1..];
                continue;
            }
        }
        break;
    }
    out.push_str(rest); out
}

fn layout_html(cfg: &Config, title: &str, body_html: &str) -> String {
    let name = cfg.name();
    let prefix_path = if let Some(p) = &cfg.path_prefix { format!("/{}/", p.trim_matches('/')) } else { "/".to_string() };
    // when prefix is weird, artifacts os_script uses build_url_path; for css link in our full build use path_prefix raw with slashes as original templates likely use their build_path helper too.
    let css_href = build_url_path(cfg.path_prefix.as_deref(), "oranda.css");
    let _ = prefix_path;
    let desc = cfg.description().unwrap_or_default();
    let mut head_extra = String::new();
    if !desc.is_empty() { head_extra.push_str(&format!("<meta name=\"description\" content=\"{}\">\n", html_escape(&desc))); }
    if let Some(analytics) = &cfg.layer.marketing.as_ref().and_then(|m| m.analytics.clone()) {
        head_extra.push_str(&analytics_script(analytics));
    }
    let theme_class = match cfg.styles().theme { Some(Theme::Light) => "light", Some(Theme::Dark) => "dark", Some(Theme::Axolight) => "axolight", Some(Theme::Axodark) => "axodark", Some(Theme::Hacker) => "hacker", Some(Theme::Cupcake) => "cupcake", None => "dark" };
    format!("<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>{}</title>\n{}<link rel=\"stylesheet\" href=\"{}\">\n<link rel=\"icon\" href=\"{}\">\n</head>\n<body class=\"{}\">\n<header><h1>{}</h1></header>\n<main>\n{}</main>\n</body>\n</html>\n", html_escape(title), head_extra, css_href, build_url_path(cfg.path_prefix.as_deref(), "favicon.ico"), theme_class, html_escape(&name), body_html)
}
fn analytics_script(a: &Analytics) -> String {
    match a {
        Analytics::Google(g) => format!("<script async src=\"https://www.googletagmanager.com/gtag/js?id={}\"></script>\n", g.tracking_id),
        Analytics::Plausible(p) => format!("<script defer data-domain=\"{}\" src=\"{}\"></script>\n", html_escape(&p.domain), html_escape(p.script_url.as_deref().unwrap_or("https://plausible.io/js/script.js"))),
        Analytics::Fathom(f) => format!("<script src=\"https://cdn.usefathom.com/script.js\" data-site=\"{}\" defer></script>\n", html_escape(&f.site)),
        Analytics::Umami(u) => format!("<script async defer data-website-id=\"{}\" src=\"{}\"></script>\n", html_escape(&u.website), html_escape(&u.script_url)),
    }
}

pub fn build_site(cfg: &Config, json_only: bool) -> OrandaResult<()> {
    clean_and_create_dist(cfg)?;
    if !json_only {
        write_default_favicon(cfg)?;
        let css = fetch_css(cfg)?;
        // write css
        let css_dest: PathBuf = if cfg.dist_dir.is_empty() { PathBuf::from("oranda.css") } else { Path::new(&cfg.dist_dir).join("oranda.css") };
        std::fs::write(&css_dest, &css).map_err(|e| write_new_asset_diag("oranda.css", &e))?;
        // full site continues after releases etc below (pages built later)
    }
    let releases = obtain_releases(cfg);
    // artifacts (in json_only and full)
    build_artifacts(cfg, releases.as_ref())?;
    if !json_only {
        build_full_pages(cfg, releases.as_ref())?;
    }
    log_success(&format!("Your site build is located in `{}`.", cfg.dist_dir));
    Ok(())
}

fn copy_dir_recursive(src: &Path, dst: &Path) -> OrandaResult<()> {
    if !src.is_dir() { return Ok(()); }
    for entry in std::fs::read_dir(src).map_err(|e| Diag::from(e))? {
        let entry = entry.map_err(|e| Diag::from(e))?;
        let from = entry.path(); let to = dst.join(entry.file_name());
        if from.is_dir() { std::fs::create_dir_all(&to).map_err(|e| Diag::from(e))?; copy_dir_recursive(&from, &to)?; }
        else if from.is_file() { std::fs::copy(&from, &to).map_err(|e| Diag::from(e))?; }
    }
    Ok(())
}

fn build_full_pages(cfg: &Config, releases: Option<&Vec<Release>>) -> OrandaResult<()> {
    let dist = Path::new(&cfg.dist_dir);
    // static dir
    if let Some(sd) = &cfg.static_dir {
        let src = Path::new(sd);
        if src.is_dir() { copy_dir_recursive(src, dist)?; }
    } else {
        let src = Path::new("static");
        if src.is_dir() { copy_dir_recursive(src, dist)?; }
    }
    // additional css
    for css in cfg.styles().additional_css.clone().unwrap_or_default() {
        dest_write_asset(cfg, &css)?;
    }
    if let Some(logo) = cfg.styles().logo.clone() { let _ = dest_write_asset(cfg, &logo); }
    if let Some(fav) = cfg.styles().favicon.clone() { let _ = dest_write_asset_named(cfg, &fav, "favicon.ico"); }
    // index from readme
    let readme_content = std::fs::read_to_string(&cfg.readme_path).unwrap_or_default();
    let body = markdown_to_html(&readme_content);
    let title = cfg.name();
    let index = layout_html(cfg, &title, &body);
    let index_dest = if cfg.dist_dir.is_empty() { PathBuf::from("index.html") } else { dist.join("index.html") };
    std::fs::write(&index_dest, index).map_err(|e| write_new_asset_diag("index.html", &e))?;
    // additional pages
    for (name, path) in &cfg.additional_pages {
        if let Ok(content) = std::fs::read_to_string(path) {
            let slug = slugify(name);
            let dir = dist.join(&slug); std::fs::create_dir_all(&dir).map_err(|e| Diag::from(e))?;
            let html = layout_html(cfg, name, &markdown_to_html(&content));
            std::fs::write(dir.join("index.html"), html).map_err(|e| write_new_asset_diag("index.html", &e))?;
        }
    }
    // changelog
    if cfg.changelog_enabled() {
        if let Some(rels) = releases {
            if !rels.is_empty() {
                let dir = dist.join("changelog"); let _ = std::fs::create_dir_all(&dir);
                let mut body = String::new();
                for r in rels { body.push_str(&format!("<h2>{}</h2>\n{}", html_escape(&r.tag), markdown_to_html(r.body.as_deref().unwrap_or("")))); }
                let _ = std::fs::write(dir.join("index.html"), layout_html(cfg, "Changelog", &body));
            }
        }
    }
    // artifacts page & script
    if artifacts_enabled(cfg) {
        let dir = dist.join("artifacts"); let _ = std::fs::create_dir_all(&dir);
        let _ = std::fs::write(dir.join("index.html"), layout_html(cfg, "Install", "<div id=\"artifacts\"></div>"));
        let js_dest = if cfg.dist_dir.is_empty() { PathBuf::from("artifacts.js") } else { dist.join("artifacts.js") };
        let _ = std::fs::write(js_dest, "// oranda artifacts\nfetch('artifacts.json').then(r=>r.json()).then(d=>console.log(d));\n");
    }
    // funding
    if cfg.funding_enabled() {
        let md_candidate = cfg.funding_md_candidate();
        if Path::new(&md_candidate).is_file() {
            if let Ok(content) = std::fs::read_to_string(&md_candidate) {
                let dir = dist.join("funding"); let _ = std::fs::create_dir_all(&dir);
                let _ = std::fs::write(dir.join("index.html"), layout_html(cfg, "Funding", &markdown_to_html(&content)));
            }
        }
    }
    // mdbook placeholder: ignore (would need mdbook rendering)
    Ok(())
}

fn dest_write_asset(cfg: &Config, source: &str) -> OrandaResult<()> {
    let filename = Path::new(source).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| source.to_string());
    dest_write_asset_named(cfg, source, &filename)
}
fn dest_write_asset_named(cfg: &Config, source: &str, dest_name: &str) -> OrandaResult<()> {
    let dest: PathBuf = if cfg.dist_dir.is_empty() { PathBuf::from(dest_name) } else { Path::new(&cfg.dist_dir).join(dest_name) };
    let bytes: Vec<u8> = if source.starts_with("http://") || source.starts_with("https://") {
        fetch_bytes(source).map_err(|fe| fe.to_diag())?
    } else {
        std::fs::read(source).map_err(|e| read_asset_diag(source, &e))?
    };
    std::fs::write(&dest, bytes).map_err(|e| write_new_asset_diag(dest_name, &e))
}
