pub struct Reloader {
    pub listeners: Arc<Mutex<Vec<std::sync::mpsc::Sender<()>>>>,
}
impl Reloader {
    pub fn new() -> Arc<Self> { Arc::new(Self { listeners: Arc::new(Mutex::new(Vec::new())) }) }
    pub fn reload(&self) {
        let mut l = self.listeners.lock().unwrap();
        for tx in l.drain(..) { let _ = tx.send(()); }
    }
    fn subscribe(&self) -> std::sync::mpsc::Receiver<()> {
        let (tx, rx) = std::sync::mpsc::channel();
        self.listeners.lock().unwrap().push(tx);
        rx
    }
}

#[derive(Clone)]
pub struct ServerConfig {
    pub dist_dir: String,
    pub path_prefix: Option<String>,
    pub port: u16,
    pub livereload: Option<Arc<Reloader>>,
}

pub fn check_build(dist_dir: &str) -> OrandaResult<()> {
    if !Path::new(dist_dir).is_dir() {
        return Err(Diag::error(format!("Could not find a build in {}", dist_dir)).with_help("Did you remember to run `oranda build`?"));
    }
    Ok(())
}

fn http_date(ts: SystemTime) -> String {
    // IMF-fixdate
    let secs = ts.duration_since(UNIX_EPOCH).unwrap_or(Duration::from_secs(0)).as_secs() as i64;
    format_http_date(secs)
}
pub fn format_http_date(mut secs: i64) -> String {
    // civil conversion
    let days = ["Thu", "Fri", "Sat", "Sun", "Mon", "Tue", "Wed"]; // 1970-01-01 Thursday
    let months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    let sec_of_day = secs.rem_euclid(86400);
    let days_since = secs.div_euclid(86400);
    let weekday = days[days_since.rem_euclid(7) as usize];
    // Howard Hinnant civil_from_days
    let z = days_since + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if m <= 2 { y + 1 } else { y };
    let hh = sec_of_day / 3600; let mm = (sec_of_day % 3600) / 60; let ss = sec_of_day % 60;
    format!("{}, {:02} {} {} {:02}:{:02}:{:02} GMT", weekday, d, months[(m - 1) as usize], year, hh, mm, ss)
}
fn parse_http_date(s: &str) -> Option<i64> {
    // IMF-fixdate only: "Thu, 08 Oct 2026 22:22:02 GMT"
    let s = s.trim();
    let parts: Vec<&str> = s.split(' ').collect();
    if parts.len() != 6 { return None; }
    let day: u32 = parts[1].parse().ok()?;
    let months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    let month = months.iter().position(|m| *m == parts[2])? as u32 + 1;
    let year: i64 = parts[3].parse().ok()?;
    let t: Vec<&str> = parts[4].split(':').collect();
    if t.len() != 3 || parts[5] != "GMT" { return None; }
    let hh: i64 = t[0].parse().ok()?; let mm: i64 = t[1].parse().ok()?; let ss: i64 = t[2].parse().ok()?;
    // days from civil
    let y = if month <= 2 { year - 1 } else { year };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = (y - era * 400) as u64;
    let mp = if month > 2 { month - 3 } else { month + 9 } as u64;
    let doy = (153 * mp + 2) / 5 + day as u64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    let days = era * 146097 + doe as i64 - 719468;
    Some(days * 86400 + hh * 3600 + mm * 60 + ss)
}

fn mime_for(path: &Path) -> &'static str {
    let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("").to_ascii_lowercase();
    match ext.as_str() {
        "html" | "htm" => "text/html",
        "css" => "text/css",
        "js" | "mjs" => "text/javascript",
        "json" => "application/json",
        "txt" => "text/plain",
        "md" => "text/markdown",
        "xml" => "text/xml",
        "xhtml" => "application/xhtml+xml",
        "svg" => "image/svg+xml",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "webp" => "image/webp",
        "ico" => "image/x-icon",
        "woff" => "font/woff",
        "woff2" => "font/woff2",
        "ttf" => "font/ttf",
        "otf" => "font/otf",
        "pdf" => "application/pdf",
        "zip" => "application/zip",
        "gz" => "application/gzip",
        "tar" => "application/x-tar",
        "wasm" => "application/wasm",
        "mp4" => "video/mp4",
        "mp3" => "audio/mpeg",
        "wav" => "audio/wav",
        "rss" => "application/rss+xml",
        "atom" => "application/atom+xml",
        "yml" | "yaml" => "text/yaml",
        "toml" => "application/toml",
        "csv" => "text/csv",
        "sh" => "application/x-sh",
        _ => "application/octet-stream",
    }
}

fn percent_decode(s: &str) -> Vec<u8> {
    let bytes = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            let hex = std::str::from_utf8(&bytes[i + 1..i + 3]).unwrap_or("");
            if let Ok(v) = u8::from_str_radix(hex, 16) { out.push(v); i += 3; continue; }
        }
        out.push(bytes[i]); i += 1;
    }
    out
}

struct Request {
    method: String,
    target: String,
    version11: bool,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}
impl Request {
    fn header(&self, name: &str) -> Option<String> {
        self.headers.iter().rev().find(|(k, _)| k.eq_ignore_ascii_case(name)).map(|(_, v)| v.clone())
    }
    fn path(&self) -> String {
        // split target at ? (fragment shouldn't be sent but original treats # as part of path? hyper Uri: query splitting at ?, fragment not allowed in URI? It accepted /a.txt#frag and treated as path? It served file - hyper Uri path includes? Actually uri /a.txt#frag might parse path /a.txt with fragment weird - for our implementation, strip query and fragment parts like a URI path.
        let mut p = self.target.clone();
        if let Some(idx) = p.find('?') { p.truncate(idx); }
        if let Some(idx) = p.find('#') { p.truncate(idx); }
        p
    }
}

enum ReadReq { Req(Request), Bad, Closed }

fn read_request(stream: &mut TcpStream, buf: &mut Vec<u8>) -> ReadReq {
    // read until header end or more
    loop {
        if let Some(pos) = find_subslice(buf, b"\r\n\r\n") {
            let head = buf.drain(..pos + 4).collect::<Vec<_>>();
            let head_str = match String::from_utf8(head) { Ok(s) => s, Err(_) => return ReadReq::Bad };
            let mut lines = head_str.split("\r\n");
            let first = lines.next().unwrap_or("");
            let parts: Vec<&str> = first.split(' ').collect();
            if parts.len() != 3 { return ReadReq::Bad; }
            let method = parts[0].to_string();
            let target = parts[1].to_string();
            if target.bytes().any(|b| b < 0x21 || b > 0x7e) { return ReadReq::Bad; }
            let version11 = parts[2] != "HTTP/1.0";
            if parts[2] != "HTTP/1.1" && parts[2] != "HTTP/1.0" && parts[2] != "HTTP/0.9" { return ReadReq::Bad; }
            let mut headers: Vec<(String, String)> = Vec::new();
            for line in lines {
                if line.is_empty() { continue; }
                if let Some((k, v)) = line.split_once(':') { headers.push((k.trim().to_string(), v.trim().to_string())); } else { return ReadReq::Bad; }
            }
            // body based on content-length (not needed generally)
            let cl: usize = headers.iter().find(|(k, _)| k.eq_ignore_ascii_case("content-length")).and_then(|(_, v)| v.parse().ok()).unwrap_or(0);
            while buf.len() < cl {
                let mut tmp = [0u8; 8192];
                match stream.read(&mut tmp) { Ok(0) => break, Ok(n) => buf.extend_from_slice(&tmp[..n]), Err(_) => break }
            }
            let body: Vec<u8> = buf.drain(..std::cmp::min(cl, buf.len())).collect();
            return ReadReq::Req(Request { method, target, version11, headers, body });
        }
        let mut tmp = [0u8; 8192];
        match stream.read(&mut tmp) {
            Ok(0) => return ReadReq::Closed,
            Ok(n) => {
                buf.extend_from_slice(&tmp[..n]);
                if buf.len() > 1024 * 1024 { return ReadReq::Bad; }
            }
            Err(_) => return ReadReq::Closed,
        }
    }
}
fn find_subslice(h: &[u8], n: &[u8]) -> Option<usize> { h.windows(n.len()).position(|w| w == n) }

struct Response {
    status: u16,
    reason: &'static str,
    headers: Vec<(String, String)>, // order, names lowercase (without date/content-length auto logic special)
    body: Vec<u8>,
    // special flags
    chunked_body: Option<Vec<u8>>, // if Some, send as one chunk
    no_content_length: bool,
}
fn reason_for(code: u16) -> &'static str {
    match code { 200=>"OK",206=>"Partial Content",301=>"Moved Permanently",304=>"Not Modified",307=>"Temporary Redirect",400=>"Bad Request",404=>"Not Found",405=>"Method Not Allowed",412=>"Precondition Failed",416=>"Range Not Satisfiable",500=>"Internal Server Error", _=>"OK" }
}
fn fmt_date_now() -> String { http_date(SystemTime::now()) }

fn send_response(stream: &mut TcpStream, req: &Request, mut resp: Response, server_is_dev: bool) {
    let is_head = req.method == "HEAD";
    let mut head = format!("HTTP/1.1 {} {}\r\n", resp.status, resp.reason);
    // headers already include order; caller includes date as final if desired - we append date if not present
    let mut has_date = false;
    for (k, v) in &resp.headers { if k.eq_ignore_ascii_case("date") { has_date = true; } head.push_str(&format!("{}: {}\r\n", k, v)); }
    if !has_date { head.push_str(&format!("date: {}\r\n", fmt_date_now())); }
    head.push_str("\r\n");
    let _ = stream.write_all(head.as_bytes());
    if !is_head {
        if let Some(chunk) = resp.chunked_body.take() {
            if !chunk.is_empty() {
                let _ = stream.write_all(format!("{:x}\r\n", chunk.len()).as_bytes());
                let _ = stream.write_all(&chunk);
                let _ = stream.write_all(b"\r\n");
            }
            let _ = stream.write_all(b"0\r\n\r\n");
        } else {
            let _ = stream.write_all(&resp.body);
        }
    } else if resp.chunked_body.is_some() {
        // HEAD on chunked endpoint: hyper strips transfer-encoding/header retained?, body omitted - headers caller handled
    }
    let _ = stream.flush();
    let _ = server_is_dev;
}

fn strip_nest<'a>(nest: &str, path: &'a str) -> Option<String> {
    if nest == "/" { return Some(path.to_string()); }
    if path == nest {
        // exact match: for nest ending with / the path equal string includes it, so fine
        return Some("/".to_string());
    }
    if let Some(rest) = path.strip_prefix(nest) {
        if nest.ends_with('/') {
            // rest is remainder without leading slash
            return Some(format!("/{}", rest));
        }
        if rest.starts_with('/') {
            return Some(rest.to_string());
        }
    }
    None
}

// Range parsing
struct RangeSpec { start: Option<u64>, end: Option<u64>, suffix: Option<u64> }
fn parse_num_no_leading_zero(s: &str) -> Option<u64> {
    if s.is_empty() || !s.chars().all(|c| c.is_ascii_digit()) { return None; }
    if s.len() > 1 && s.starts_with('0') { return None; }
    s.parse::<u64>().ok()
}
fn parse_ranges(v: &str) -> Option<Vec<RangeSpec>> {
    // HTTP parser trims OWS; our header value already trimmed. Unit must be exactly "bytes"
    let rest = v.strip_prefix("bytes=")?;
    if rest.is_empty() { return None; }
    let mut specs = Vec::new();
    for part in rest.split(',') {
        let part = part.trim_matches(|c| c == ' ' || c == '\t');
        // note: space after comma trimmed; internal spaces cause parse fail because numbers include them
        let (a, b) = part.split_once('-')?;
        if a.contains(' ') || b.contains(' ') { return None; }
        if a.is_empty() && b.is_empty() { return None; }
        if a.is_empty() {
            let suf = parse_num_no_leading_zero(b)?;
            specs.push(RangeSpec { start: None, end: None, suffix: Some(suf) });
        } else {
            let start = parse_num_no_leading_zero(a)?;
            let end = if b.is_empty() { None } else { Some(parse_num_no_leading_zero(b)?) };
            specs.push(RangeSpec { start: Some(start), end, suffix: None });
        }
    }
    Some(specs)
}
fn satisfiable(spec: &RangeSpec, len: u64) -> Option<(u64, u64)> {
    if len == 0 { return None; }
    if let Some(suf) = spec.suffix {
        if suf == 0 || suf > len { return None; }
        return Some((len - suf, len - 1));
    }
    let start = spec.start?;
    if start >= len { return None; }
    let end = match spec.end { Some(e) => { if e < start { return None; } std::cmp::min(e, len - 1) }, None => len - 1 };
    Some((start, end))
}

pub fn serve_file_request(cfg: &ServerConfig, req: &Request, remainder: &str) -> Response {
    // 405 handled by caller router? ServeDir itself returns 405 for non-GET/HEAD with allow header.
    if req.method != "GET" && req.method != "HEAD" {
        // Order differs dev vs serve: caller can adjust? We'll return headers in serve order and dev caller reorders externally - handled in handle_connection based on cfg.livereload
        return Response { status: 405, reason: reason_for(405), headers: vec![("allow".into(), "GET,HEAD".into()), ("content-length".into(), "0".into())], body: vec![], chunked_body: None, no_content_length: false };
    }
    let decoded_bytes = percent_decode(remainder);
    let decoded = String::from_utf8_lossy(&decoded_bytes).to_string();
    // component handling
    let path_obj = Path::new(&decoded);
    let mut file_path = PathBuf::from(&cfg.dist_dir);
    let mut has_parent = false;
    for comp in path_obj.components() {
        match comp {
            Component::Normal(c) => file_path.push(c),
            Component::CurDir => {}
            Component::RootDir => {}
            Component::ParentDir => { has_parent = true; }
            Component::Prefix(_) => {}
        }
    }
    if has_parent {
        return not_found();
    }
    // metadata
    let md = match std::fs::metadata(&file_path) { Ok(m) => m, Err(_) => return not_found() };
    if md.is_dir() {
        if !remainder.ends_with('/') {
            // redirect to remainder + "/"
            let location = format!("{}/", remainder);
            return Response { status: 307, reason: reason_for(307), headers: vec![("location".into(), location), ("content-length".into(), "0".into())], body: vec![], chunked_body: None, no_content_length: false };
        }
        file_path.push("index.html");
        if !Path::new(&file_path).is_file() { return not_found(); }
    } else if !md.is_file() {
        return not_found();
    }
    serve_existing_file(cfg, req, &file_path)
}
fn not_found() -> Response {
    Response { status: 404, reason: reason_for(404), headers: vec![("content-length".into(), "0".into())], body: vec![], chunked_body: None, no_content_length: false }
}

fn serve_existing_file(cfg: &ServerConfig, req: &Request, file_path: &Path) -> Response {
    let md = match std::fs::metadata(file_path) { Ok(m) => m, Err(_) => return not_found() };
    let mtime = md.modified().unwrap_or(UNIX_EPOCH);
    let mtime_secs = mtime.duration_since(UNIX_EPOCH).unwrap_or(Duration::from_secs(0)).as_secs() as i64;
    let last_mod = http_date(mtime);
    // preconditions
    if let Some(v) = req.header("if-unmodified-since") {
        if let Some(t) = parse_http_date(&v) {
            if mtime_secs > t {
                return Response { status: 412, reason: reason_for(412), headers: vec![("content-length".into(), "0".into())], body: vec![], chunked_body: None, no_content_length: false };
            }
        }
    }
    if let Some(v) = req.header("if-modified-since") {
        if let Some(t) = parse_http_date(&v) {
            if mtime_secs <= t {
                // 304: only date header (added by sender)
                return Response { status: 304, reason: reason_for(304), headers: vec![], body: vec![], chunked_body: None, no_content_length: true };
            }
        }
    }
    let len = md.len();
    let mime = mime_for(file_path);
    let contents = match std::fs::read(file_path) { Ok(c) => c, Err(_) => return not_found() };
    let mut headers: Vec<(String, String)> = Vec::new();
    headers.push(("content-type".into(), mime.to_string()));
    headers.push(("accept-ranges".into(), "bytes".into()));
    if let Some(ae) = req.header("accept-encoding") {
        let parts: Vec<String> = ae.split(',').map(|p| p.trim().split(';').next().unwrap_or("").trim().to_ascii_lowercase()).collect();
        if parts.iter().any(|p| p == "identity") {
            headers.push(("content-encoding".into(), "identity".into()));
        }
    }
    headers.push(("last-modified".into(), last_mod));
    // Range
    let mut status = 200;
    let mut body: Vec<u8> = contents.clone();
    let mut is_range = false;
    if let Some(range_v) = req.header("range") {
        is_range = true;
        let specs_opt = parse_ranges(range_v.trim());
        let mut range_error_body: Option<Vec<u8>> = None;
        let mut range_pair: Option<(u64, u64)> = None;
        let mut ok = false;
        if let Some(specs) = specs_opt {
            let sats: Vec<Option<(u64, u64)>> = specs.iter().map(|s| satisfiable(s, len)).collect();
            if specs.len() > 1 {
                if sats.iter().all(|s| s.is_some()) {
                    range_error_body = Some(b"Cannot serve multipart range requests".to_vec());
                }
            } else if let Some(Some(pair)) = sats.into_iter().next() {
                range_pair = Some(pair); ok = true;
            }
        }
        if !ok {
            let b = range_error_body.unwrap_or_default();
            headers.push(("content-range".into(), format!("bytes */{}", len)));
            headers.push(("content-length".into(), format!("{}", b.len())));
            return Response { status: 416, reason: reason_for(416), headers, body: b, chunked_body: None, no_content_length: false };
        }
        let (st, en) = range_pair.unwrap();
        status = 206;
        body = contents[(st as usize)..=(en as usize)].to_vec();
        headers.push(("content-range".into(), format!("bytes {}-{}/{}", st, en, len)));
    }
    // livereload injection for dev: if mime is text/html and status 200/206
    if cfg.livereload.is_some() && mime == "text/html" && (status == 200 || status == 206) {
        body.extend_from_slice(LIVERELOAD_SCRIPT.as_bytes());
    }
    headers.push(("content-length".into(), format!("{}", body.len())));
    let _ = is_range;
    Response { status, reason: reason_for(status), headers, body, chunked_body: None, no_content_length: false }
}

fn should_close(req: &Request) -> bool {
    if let Some(c) = req.header("connection") {
        let v = c.to_ascii_lowercase();
        if v.contains("close") { return true; }
        if v.contains("keep-alive") { return false; }
    }
    !req.version11
}

fn handle_connection(mut stream: TcpStream, cfg: ServerConfig) {
    let _ = stream.set_nodelay(true);
    let mut buf: Vec<u8> = Vec::new();
    loop {
        let req = match read_request(&mut stream, &mut buf) {
            ReadReq::Closed => break,
            ReadReq::Bad => {
                let resp = Response { status: 400, reason: reason_for(400), headers: vec![("content-length".into(), "0".into())], body: vec![], chunked_body: None, no_content_length: false };
                // send with dummy request
                let dummy = Request { method: "GET".into(), target: "/".into(), version11: true, headers: vec![], body: vec![] };
                send_response(&mut stream, &dummy, resp, cfg.livereload.is_some());
                break;
            }
            ReadReq::Req(r) => r,
        };
        let path = req.path();
        let close = should_close(&req);
        // livereload endpoints at root (any method)
        if let Some(reloader) = &cfg.livereload {
            if path == "/tower-livereload/long-name-to-avoid-collisions/back-up" {
                if req.method == "HEAD" {
                    let resp = Response { status: 200, reason: "OK", headers: vec![("content-type".into(), "text/plain".into())], body: vec![], chunked_body: None, no_content_length: true };
                    send_response(&mut stream, &req, resp, true);
                } else {
                    let resp = Response { status: 200, reason: "OK", headers: vec![("content-type".into(), "text/plain".into()), ("transfer-encoding".into(), "chunked".into())], body: vec![], chunked_body: Some(b"Ok".to_vec()), no_content_length: true };
                    send_response(&mut stream, &req, resp, true);
                }
                if close { break; } else { continue; }
            }
            if path == "/tower-livereload/long-name-to-avoid-collisions/long-poll" {
                // headers
                let head = if req.method == "HEAD" {
                    format!("HTTP/1.1 200 OK\r\ncontent-type: text/event-stream\r\ndate: {}\r\n\r\n", fmt_date_now())
                } else {
                    format!("HTTP/1.1 200 OK\r\ncontent-type: text/event-stream\r\ntransfer-encoding: chunked\r\ndate: {}\r\n\r\n", fmt_date_now())
                };
                let _ = stream.write_all(head.as_bytes());
                let _ = stream.flush();
                if req.method != "HEAD" {
                    let rx = reloader.subscribe();
                    // Block until reload signal or client disconnect - Receiver recv blocks; if client closes, writes fail later.
                    // Set stream read timeout? We just wait on channel.
                    let _ = rx.recv();
                    let _ = stream.write_all(b"0\r\n\r\n");
                    let _ = stream.flush();
                }
                break;
            }
        }
        // file routing through nest
        let prefix_str = cfg.path_prefix.clone().unwrap_or_default();
        let nest = format!("/{}", prefix_str);
        let resp = if let Some(remainder) = strip_nest(&nest, &path) {
            let mut r = serve_file_request(&cfg, &req, &remainder);
            // dev 405 header order: content-length before allow
            if cfg.livereload.is_some() && r.status == 405 {
                r.headers = vec![("content-length".into(), "0".into()), ("allow".into(), "GET,HEAD".into())];
            }
            r
        } else {
            // axum fallback 405? For non-GET/HEAD to a path outside nest, original serve gave 405 too (since route exists as fallback?) - tested POST to myproj route only. Check: POST to / (outside nest) in serve - it returned ??? earlier POST "/" in dev with no prefix gave 405, in serve with prefix POST /unknown gave 405 in urllib tests (all routes are ServeDir fallback). For axum nested router, unmatched paths give 404 regardless method, except ServeDir fallback handles method check before nest? Need our: if method not GET/HEAD, return 405 regardless of nest match
            if req.method != "GET" && req.method != "HEAD" {
                let headers = if cfg.livereload.is_some() { vec![("content-length".into(), "0".into()), ("allow".into(), "GET,HEAD".into())] } else { vec![("allow".into(), "GET,HEAD".into()), ("content-length".into(), "0".into())] };
                Response { status: 405, reason: reason_for(405), headers, body: vec![], chunked_body: None, no_content_length: false }
            } else {
                not_found()
            }
        };
        send_response(&mut stream, &req, resp, cfg.livereload.is_some());
        if close { break; }
    }
}

pub fn run_server(cfg: ServerConfig, print_success: bool) -> OrandaResult<()> {
    check_build(&cfg.dist_dir)?;
    let addr = format!("127.0.0.1:{}", cfg.port);
    // bind; on failure emulate hyper panic for serve (caller handles dev separate)
    let listener = match TcpListener::bind(&addr) {
        Ok(l) => l,
        Err(e) => {
            // success message is printed before bind in serve flow - caller prints before calling? Our serve command will print before run_server bind? To match: print success here before bind if print_success.
            if print_success {
                let prefix = cfg.path_prefix.clone().unwrap_or_default();
                log_success(&format!("Your project is available at: http://127.0.0.1:{}/{}", cfg.port, prefix));
            }
            let payload = format!("error binding to {}: error creating server listener: {}", addr, e);
            print_panic("/usr/local/cargo/registry/src/index.crates.io-6f17d22bba15001f/hyper-0.14.28/src/server/server.rs:81:13", &payload);
            std::process::exit(255);
        }
    };
    if print_success {
        let prefix = cfg.path_prefix.clone().unwrap_or_default();
        log_success(&format!("Your project is available at: http://127.0.0.1:{}/{}", cfg.port, prefix));
    }
