fn extract_toml_cause(msg: &str) -> Option<String> {
    // toml 1.x errors look like:
    // TOML parse error at line 1, column 8\n  |\n1 | bad = [\n  |        ^\ninvalid string\nexpected ...
    // We can approximate old messages for EOF cases found in msg
    // Find "at line X, column Y"
    // Heuristic: if msg contains "unexpected end" or eof related, but toml 1.x phrasing differs.
    // We'll return a compact transform: last meaningful lines joined?
    // For cases in tests, exact phrasing from newer toml will differ from original; keep first parse position and a lowercase detail if available.
    // Try to locate "unexpected eof" synonyms in toml errors: toml crate may say "invalid array\nexpected ']'"
    // Return None to fall back.
    None
}

fn toml_kind_name(v: &toml::Value) -> String {
    match v {
        toml::Value::String(s) => format!("string \"{}\"", s),
        toml::Value::Integer(i) => format!("integer `{}`", i),
        toml::Value::Float(f) => format!("floating point `{}`", f),
        toml::Value::Boolean(b) => format!("boolean `{}`", b),
        toml::Value::Datetime(dt) => format!("datetime `{}`", dt),
        toml::Value::Array(_) => "sequence".to_string(),
        toml::Value::Table(_) => "map".to_string(),
    }
}
fn toml_kind_value(v: &toml::Value) -> String { toml_kind_name(v) }

pub fn find_mdbook(cfg: &crate::config::Config) -> OrandaResult<Option<MdbookInfo>> {
    if !cfg.mdbook_enabled() { return Ok(None); }
    let layer = cfg.mdbook_layer();
    if let Some(p) = layer.path.clone() {
        // specified path check: relative non-empty and doesn't exist -> Specified path error, absolute/empty/. bypass ?
        // Observed: relative missing (nope, ./nope, https://...) -> Specified path; absolute missing -> goes to load; empty string -> load at ""; "." -> load at "" (root_display empty)
        let path_obj = Path::new(&p);
        let is_abs = path_obj.is_absolute();
        if !is_abs && !p.is_empty() && p != "." && !path_obj.exists() {
            return Err(Diag::error(format!("Specified path `{}` was not found on your filesystem!", p))
                .with_help("Make sure you specify your path relative to the oranda.json/manifest file/README file of your project!"));
        }
        let root_display = if p.is_empty() || p == "." {
            "".to_string()
        } else if is_abs {
            p.clone()
        } else {
            // custom relative path that exists: original uses absolute path (cwd join) as root_display for mdbook load/watch
            let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
            cwd.join(&p).display().to_string()
        };
        let info = load_mdbook(&root_display)?;
        return Ok(Some(info));
    }
    // Auto discovery: root book.toml, then docs/book.toml
    if Path::new("book.toml").is_file() {
        let info = load_mdbook("")?;
        return Ok(Some(info));
    }
    if Path::new("docs/book.toml").is_file() {
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let root_display = cwd.join("docs").display().to_string();
        let info = load_mdbook(&root_display)?;
        return Ok(Some(info));
    }
    Ok(None)
}
