use crate::config::*;
use crate::diag::*;
use crate::server::*;
use crate::site::*;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::SystemTime;

fn specified_path_err(p: &str) -> Diag {
    Diag::error(format!("Specified path `{}` was not found on your filesystem!", p))
        .with_help("Make sure you specify your path relative to the oranda.json/manifest file/README file of your project!")
}

pub fn gather_watched_paths(cfg: &Config, include_paths: &[String]) -> OrandaResult<Vec<String>> {
    let mut watched: Vec<String> = Vec::new();
    // readme
    if Path::new(&cfg.readme_path).exists() {
        watched.push(cfg.readme_path.clone());
    }
    // oranda.json - if a config file was successfully read
    if cfg.has_oranda_file {
        watched.push("oranda.json".to_string());
    }
    // funding
    if cfg.funding_enabled() {
        let yml = cfg.funding_yml_candidate();
        if Path::new(&yml).exists() { watched.push(yml); }
        let md = cfg.funding_md_candidate();
        if Path::new(&md).exists() { watched.push(md); }
    }
    // additional pages
    for (_name, p) in &cfg.additional_pages {
        let obj = Path::new(p);
        if obj.is_absolute() || p.is_empty() || p == "." {
            if obj.exists() && !p.is_empty() && p != "." {
                watched.push(p.clone());
            } else if obj.exists() && p == "." {
                // "." as additional page: original did not watch it (only oranda.json) in test - because(?) maybe additional pages are filtered to files? In dir test additional_page dir "mydir" WAS watched. "." exists but wasn't watched.
                // Skip "." and ""
            }
            // absolute nonexistent silently skip
        } else {
            if !obj.exists() {
                return Err(specified_path_err(p));
            }
            watched.push(p.clone());
        }
    }
    // mdbook
    if let Some(info) = crate::mdbook::find_mdbook(cfg)? {
        watched.push(info.book_toml_watch);
        watched.push(info.src_watch);
    }
    // include paths: filter existing
    for p in include_paths {
        if Path::new(p).exists() { watched.push(p.clone()); }
    }
    Ok(watched)
}

// ---------- watcher snapshot ----------
#[derive(Clone, PartialEq, Debug)]
struct FileState {
    mtime: Option<SystemTime>,
    len: u64,
    is_dir: bool,
    mode: u32,
}
fn state_for(p: &Path) -> Option<FileState> {
    let md = std::fs::metadata(p).ok()?;
    let mode = {
        #[cfg(unix)]
        { use std::os::unix::fs::PermissionsExt; md.permissions().mode() }
        #[cfg(not(unix))]
        { 0 }
    };
    Some(FileState { mtime: md.modified().ok(), len: md.len(), is_dir: md.is_dir(), mode })
}
fn snapshot(watched: &[String], cwd: &Path) -> BTreeMap<PathBuf, Option<FileState>> {
    let mut map = BTreeMap::new();
    for w in watched {
        let p = Path::new(w);
        let abs = if p.is_absolute() { p.to_path_buf() } else { cwd.join(p) };
        collect(&abs, &mut map);
    }
    map
}
fn collect(p: &Path, map: &mut BTreeMap<PathBuf, Option<FileState>>) {
    let st = state_for(p);
    let is_dir = st.as_ref().map(|s| s.is_dir).unwrap_or(false);
    map.insert(p.to_path_buf(), st);
    if is_dir {
        if let Ok(entries) = std::fs::read_dir(p) {
            for e in entries.flatten() { collect(&e.path(), map); }
        }
    }
}
fn diff_paths(old: &BTreeMap<PathBuf, Option<FileState>>, new: &BTreeMap<PathBuf, Option<FileState>>) -> Vec<PathBuf> {
    let mut out = Vec::new();
    for (k, v) in new.iter() {
        match old.get(k) {
            None => out.push(k.clone()),
            Some(ov) if ov != v => out.push(k.clone()),
            _ => {}
        }
    }
    for k in old.keys() {
        if !new.contains_key(k) { out.push(k.clone()); }
    }
    out
}

pub fn dev_command(port: Option<u16>, no_first_build: bool, include_paths: Vec<String>) -> OrandaResult<()> {
    let port = port.unwrap_or(7979);
    let cfg = load_config()?;
    let watched = gather_watched_paths(&cfg, &include_paths)?;
    // Validate watcher creation feasibility for problematic paths like "/" - configuring notify would fail walking permission
    // We emulate: if any watched path is "/" (root), return watcher error like original
    for w in &watched {
        if w == "/" {
            let d = Diag::error("We were unable to watch your filesystem for changes")
                .with_cause("Permission denied (os error 13) about [\"/etc/ssl/private\"]".to_string())
                .with_help("Make sure that oranda has privileges to set up file watchers!");
            return Err(d);
        }
    }
    log_info(&format!("Found {} paths to watch, starting watch...", watched.len()));
    if verbose() {
        // Debug format is Rust Debug of Vec<String>? watched entries are PathBuf in original - Debug prints quoted strings
        log_debug(&format!("Files watched: {:?}", watched));
    }
    if !no_first_build {
        build_site(&cfg, false)?;
    }
    // spawn server
    let reloader = Reloader::new();
    let server_cfg = ServerConfig { dist_dir: cfg.dist_dir.clone(), path_prefix: cfg.path_prefix.clone(), port, livereload: Some(reloader.clone()) };
    spawn_dev_server(server_cfg);
    // success message
    match &cfg.path_prefix {
        Some(p) => log_success(&format!("Your project is available at: http://127.0.0.1:{}/{}", port, p)),
        None => log_success(&format!("Your project is available at: http://127.0.0.1:{}", port)),
    }
    // watch loop polling
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let mut last = snapshot(&watched, &cwd);
    loop {
        std::thread::sleep(std::time::Duration::from_millis(100));
        let cur = snapshot(&watched, &cwd);
        let changed = diff_paths(&last, &cur);
        if changed.is_empty() { last = cur; continue; }
        // debounce 1 sec gathering more changes
        let mut all_changed: Vec<PathBuf> = changed.clone();
        let mut latest = cur.clone();
        let start = std::time::Instant::now();
        while start.elapsed() < std::time::Duration::from_millis(1050) {
            std::thread::sleep(std::time::Duration::from_millis(100));
            let c2 = snapshot(&watched, &cwd);
            let d2 = diff_paths(&latest, &c2);
            for p in d2 { if !all_changed.contains(&p) { all_changed.push(p); } }
            latest = c2;
        }
        // remove paths that are duplicates & format as absolute strings debug list
        // Original paths display as a Rust Debug Vec<PathBuf> - order observed typically single path. We'll sort by string for determinism when many.
        // But for rename they showed set order - sorting is defensible.
        let mut display_paths: Vec<String> = all_changed.iter().map(|p| p.display().to_string()).collect();
        // Preserve discovery order except dedupe; no sort
        display_paths.dedup();
        log_info(&format!("Path(s) {:?} changed, rebuilding...", display_paths));
        // rebuild: reload config and build; if config load or build fails, print diagnostics to stderr and continue
        match load_config() {
            Ok(new_cfg) => {
                match build_site(&new_cfg, false) {
                    Ok(()) => { reloader.reload(); }
                    Err(d) => { eprint_diag(&d); }
                }
            }
            Err(d) => { eprint_diag(&d); }
        }
        last = snapshot(&watched, &cwd);
    }
}
RS
"}

