cat > src/generate.rs <<'RS'
use crate::config::*;
use crate::diag::*;
use std::io::{Read, Write};
use std::os::unix::io::AsRawFd;
use std::path::Path;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PromptErrorKind { NotTTY, OperationInterrupted, OperationCanceled }
impl PromptErrorKind {
    pub fn as_str(&self) -> &'static str {
        match self { Self::NotTTY => "NotTTY", Self::OperationInterrupted => "OperationInterrupted", Self::OperationCanceled => "OperationCanceled" }
    }
}

struct RawGuard { fd: i32, orig: libc::termios }
impl RawGuard {
    fn new(file: &std::fs::File) -> Result<Self, PromptErrorKind> {
        let fd = file.as_raw_fd();
        unsafe {
            let mut orig: libc::termios = std::mem::zeroed();
            if libc::tcgetattr(fd, &mut orig) != 0 { return Err(PromptErrorKind::NotTTY); }
            let mut raw = orig;
            // cfmakeraw equivalent
            raw.c_iflag &= !(libc::BRKINT | libc::ICRNL | libc::INPCK | libc::ISTRIP | libc::IXON);
            raw.c_oflag &= !(libc::OPOST);
            raw.c_cflag |= libc::CS8;
            raw.c_lflag &= !(libc::ECHO | libc::ICANON | libc::IEXTEN | libc::ISIG);
            raw.c_cc[libc::VMIN as usize] = 1;
            raw.c_cc[libc::VTIME as usize] = 0;
            if libc::tcsetattr(fd, libc::TCSADRAIN, &raw) != 0 { return Err(PromptErrorKind::NotTTY); }
            Ok(Self { fd, orig })
        }
    }
}
impl Drop for RawGuard {
    fn drop(&mut self) { unsafe { libc::tcsetattr(self.fd, libc::TCSADRAIN, &self.orig); } }
}

fn tty_width(fd: i32) -> usize {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 { return ws.ws_col as usize; }
    }
    if let Ok(c) = std::env::var("COLUMNS") { if let Ok(n) = c.parse::<usize>() { if n > 0 { return n; } } }
    80
}

fn use_color() -> bool {
    if std::env::var_os("NO_COLOR").is_some() { return false; }
    if let Ok(t) = std::env::var("TERM") { if t == "dumb" { return false; } }
    true
}

struct Frame {
    lines: Vec<String>, // logical lines with ANSI if color
    plain_lines: Vec<String>,
    caret_line_idx: usize, // logical line index of prompt
    caret_col_in_line: usize, // char display index in prompt logical line
}

fn physical_rows(plain: &str, width: usize) -> usize {
    let w = disp_width(plain);
    if w == 0 { 1 } else { (w + width - 1) / width }
}
fn caret_pos(plain_lines: &[String], caret_line_idx: usize, caret_col: usize, width: usize) -> (usize, usize, usize) {
    // returns total rows, caret row offset, caret physical col (0-based)
    let mut total = 0usize;
    for l in plain_lines { total += physical_rows(l, width); }
    let mut row_before = 0usize;
    for i in 0..caret_line_idx { row_before += physical_rows(&plain_lines[i], width); }
    let crow = if width == 0 { 0 } else { caret_col / width };
    let ccol = if width == 0 { caret_col } else { caret_col % width };
    (total, row_before + crow, ccol)
}

struct Prompt<'a> {
    question: &'a str,
    help: Option<&'a str>,
    default: bool,
}

enum Key {
    Char(char), Enter, Backspace, Esc, Interrupted, Left, Right, Home, End, Delete, CtrlA, CtrlE, CtrlK, CtrlU, CtrlW, Other,
}

struct KeyReader {
    file: std::fs::File,
    buf: Vec<u8>,
    pos: usize,
}
impl KeyReader {
    fn read_byte(&mut self) -> Option<u8> {
        if self.pos < self.buf.len() { let b = self.buf[self.pos]; self.pos += 1; return Some(b); }
        let mut tmp = [0u8; 64];
        match self.file.read(&mut tmp) {
            Ok(0) => None,
            Ok(n) => { self.buf = tmp[..n].to_vec(); self.pos = 0; self.read_byte() }
            Err(_) => None,
        }
    }
    fn peek_available(&mut self) -> bool {
        if self.pos < self.buf.len() { return true; }
        // poll with 10ms timeout
        let fd = self.file.as_raw_fd();
        unsafe {
            let mut pfd: libc::pollfd = std::mem::zeroed();
            pfd.fd = fd; pfd.events = libc::POLLIN;
            libc::poll(&mut pfd, 1, 10) > 0 && (pfd.revents & libc::POLLIN) != 0
        }
    }
    fn read_key(&mut self) -> Key {
        let Some(b) = self.read_byte() else { return Key::Interrupted; };
        match b {
            b'\r' | b'\n' => Key::Enter,
            0x03 => Key::Interrupted,
            0x7f | 0x08 => Key::Backspace,
            0x01 => Key::CtrlA,
            0x05 => Key::CtrlE,
            0x0b => Key::CtrlK,
            0x15 => Key::CtrlU,
            0x17 => Key::CtrlW,
            0x1b => {
                if !self.peek_available() { return Key::Esc; }
                let Some(b2) = self.read_byte() else { return Key::Esc; };
                if b2 == b'[' {
                    // CSI sequence: read until final byte @-~
                    let mut seq: Vec<u8> = Vec::new();
                    loop {
                        let Some(c) = self.read_byte() else { break };
                        seq.push(c);
                        if (0x40..=0x7e).contains(&c) { break; }
                        if seq.len() > 10 { break; }
                    }
                    match seq.last() {
                        Some(b'C') => Key::Right,
                        Some(b'D') => Key::Left,
                        Some(b'H') => Key::Home,
                        Some(b'F') => Key::End,
                        Some(b'~') => {
                            let s = String::from_utf8_lossy(&seq).to_string();
                            if s.starts_with('3') { Key::Delete } else if s.starts_with('1') || s.starts_with('7') { Key::Home } else if s.starts_with('4') || s.starts_with('8') { Key::End } else { Key::Other }
                        }
                        _ => Key::Other,
                    }
                } else if b2 == b'O' {
                    match self.read_byte() { Some(b'C') => Key::Right, Some(b'D') => Key::Left, Some(b'H') => Key::Home, Some(b'F') => Key::End, _ => Key::Other }
                } else {
                    Key::Esc
                }
            }
            0x09 => Key::Other,
            0x00..=0x1f => Key::Other,
            _ => {
                // UTF-8 sequence
                let mut bytes = vec![b];
                let need = if b >= 0xf0 { 3 } else if b >= 0xe0 { 2 } else if b >= 0xc0 { 1 } else { 0 };
                for _ in 0..need { if let Some(x) = self.read_byte() { bytes.push(x); } }
                match String::from_utf8(bytes) { Ok(s) => s.chars().next().map(Key::Char).unwrap_or(Key::Other), Err(_) => Key::Other }
            }
        }
    }
}

fn build_frame(p: &Prompt, input: &str, cursor: usize, error: Option<&str>, color: bool) -> Frame {
    let hint = if p.default { "Y/n" } else { "y/N" };
    let mut lines: Vec<String> = Vec::new();
    let mut plain: Vec<String> = Vec::new();
    if let Some(e) = error {
        if color {
            lines.push(format!("\x1b[38;5;9m#\x1b[39m \x1b[38;5;9m{}\x1b[39m", e));
        } else { lines.push(format!("# {}", e)); }
        plain.push(format!("# {}", e));
    }
    let prompt_plain = format!("? >o_o< {} ({}) {} ", p.question, hint, input);
    if color {
        lines.push(format!("\x1b[38;5;2m? >o_o<\x1b[39m {} ({}) {} ", p.question, hint, input));
    } else { lines.push(prompt_plain.clone()); }
    let caret_line_idx = plain.len();
    // caret col: position of char at input start + cursor (chars index)
    let input_start_plain_len = format!("? >o_o< {} ({}) ", p.question, hint).chars().map(char_width).sum::<usize>();
    plain.push(prompt_plain);
    if let Some(h) = p.help {
        if color {
            lines.push(format!("\x1b[38;5;14m[\x1b[39m\x1b[38;5;14m{}\x1b[39m\x1b[38;5;14m]\x1b[39m", h));
        } else { lines.push(format!("[{}]", h)); }
        plain.push(format!("[{}]", h));
    }
    let caret_col = input_start_plain_len + input.chars().take(cursor).map(char_width).sum::<usize>();
    Frame { lines, plain_lines: plain, caret_line_idx, caret_col_in_line: caret_col }
}

fn prompt_confirm_inner(p: Prompt) -> Result<Option<bool>, PromptErrorKind> {
    // returns Ok(Some(bool)) answered, Err(kind) for NotTTY/interrupt/cancel
    // The caller decides skippable handling.
    let tty = std::fs::OpenOptions::new().read(true).write(true).open("/dev/tty").map_err(|_| PromptErrorKind::NotTTY)?;
    let fd = tty.as_raw_fd();
    // Verify is a tty
    if unsafe { libc::isatty(fd) } != 1 { return Err(PromptErrorKind::NotTTY); }
    let _raw = RawGuard::new(&tty)?;
    let width = tty_width(fd);
    let color = use_color();
    let mut stderr = std::io::stderr();
    let mut input: Vec<char> = Vec::new();
    let mut cursor = 0usize;
    let mut error: Option<String> = None;
    let mut first_draw = true;
    let mut reader = KeyReader { file: tty, buf: Vec::new(), pos: 0 };
    loop {
        let input_s: String = input.iter().collect();
        let frame = build_frame(&p, &input_s, cursor, error.as_deref(), color);
        let (total, caret_row, caret_col) = caret_pos(&frame.plain_lines, frame.caret_line_idx, frame.caret_col_in_line, width);
        if first_draw {
            let _ = write!(stderr, "\x1b[?25l\x1b[?25l\x1b[?25l");
            for line in &frame.lines { let _ = write!(stderr, "{}\r\n", line); }
            let up = total - caret_row;
            if up > 0 { let _ = write!(stderr, "\x1b[{}A", up); }
            let _ = write!(stderr, "\x1b[{}G\x1b[?25h", caret_col + 1);
            let _ = stderr.flush();
            first_draw = false;
        } else {
            // redraw already done in key handling below? We handle redraw here at top for each iteration after first by clearing previous frame.
            // prev frame info stored in variables below via a separate path - this branch should not happen because we redraw inline after key and continue to read next key without looping to draw.
            unreachable!();
        }
        // inner key loop with redraws
        // We need mutable prev frame tracking; implement as nested loop
        let mut prev = frame;
        loop {
            let key = reader.read_key();
            match key {
                Key::Interrupted => {
                    // move down 1, col1, show cursor
                    let _ = write!(stderr, "\x1b[1B\x1b[1G\x1b[?25h");
                    let _ = stderr.flush();
                    return Err(PromptErrorKind::OperationInterrupted);
                }
                Key::Esc => {
                    // clear prev frame and draw canceled line
                    redraw_clear(&mut stderr, &prev, width);
                    if color {
                        let _ = write!(stderr, "\x1b[?25l\x1b[38;5;2m? >o_o<\x1b[39m {} \x1b[38;5;1m<canceled>\x1b[39m\r\n\x1b[?25l\x1b[?25h", p.question);
                    } else {
                        let _ = write!(stderr, "? >o_o< {} <canceled>\r\n", p.question);
                    }
                    let _ = stderr.flush();
                    return Err(PromptErrorKind::OperationCanceled);
                }
                Key::Enter => {
                    let input_s2: String = input.iter().collect();
                    let parsed: Option<bool> = if input_s2.is_empty() { Some(p.default) } else {
                        match input_s2.to_ascii_lowercase().as_str() {
                            "y" | "yes" => Some(true),
                            "n" | "no" => Some(false),
                            _ => None,
                        }
                    };
                    if let Some(ans) = parsed {
                        redraw_clear(&mut stderr, &prev, width);
                        if color {
                            let _ = write!(stderr, "\x1b[?25l\x1b[38;5;10m>\x1b[39m {} \x1b[38;5;14m{}\x1b[39m\r\n\x1b[?25l\x1b[?25h", p.question, if ans { "Yes" } else { "No" });
                        } else {
                            let _ = write!(stderr, "> {} {}\r\n", p.question, if ans { "Yes" } else { "No" });
                        }
                        let _ = stderr.flush();
                        return Ok(Some(ans));
                    } else {
                        error = Some("Invalid answer, try typing 'y' for yes or 'n' for no".to_string());
                        let new_frame = build_frame(&p, &input_s2, cursor, error.as_deref(), color);
                        redraw_replace(&mut stderr, &prev, &new_frame, width);
                        prev = new_frame;
                    }
                }
                Key::Backspace => {
                    if cursor > 0 { cursor -= 1; input.remove(cursor); }
                    let s: String = input.iter().collect();
                    let new_frame = build_frame(&p, &s, cursor, error.as_deref(), color);
                    redraw_replace(&mut stderr, &prev, &new_frame, width); prev = new_frame;
                }
                Key::Delete => {
                    if cursor < input.len() { input.remove(cursor); }
                    let s: String = input.iter().collect();
                    let new_frame = build_frame(&p, &s, cursor, error.as_deref(), color);
                    redraw_replace(&mut stderr, &prev, &new_frame, width); prev = new_frame;
                }
                Key::Left => { if cursor > 0 { cursor -= 1; } let s: String = input.iter().collect(); let nf = build_frame(&p, &s, cursor, error.as_deref(), color); redraw_replace(&mut stderr, &prev, &nf, width); prev = nf; }
                Key::Right => { if cursor < input.len() { cursor += 1; } let s: String = input.iter().collect(); let nf = build_frame(&p, &s, cursor, error.as_deref(), color); redraw_replace(&mut stderr, &prev, &nf, width); prev = nf; }
                Key::Home | Key::CtrlA => { cursor = 0; let s: String = input.iter().collect(); let nf = build_frame(&p, &s, cursor, error.as_deref(), color); redraw_replace(&mut stderr, &prev, &nf, width); prev = nf; }
                Key::End | Key::CtrlE => { cursor = input.len(); let s: String = input.iter().collect(); let nf = build_frame(&p, &s, cursor, error.as_deref(), color); redraw_replace(&mut stderr, &prev, &nf, width); prev = nf; }
                Key::CtrlU => { input.clear(); cursor = 0; let nf = build_frame(&p, "", cursor, error.as_deref(), color); redraw_replace(&mut stderr, &prev, &nf, width); prev = nf; }
                Key::CtrlK => { input.truncate(cursor); let s: String = input.iter().collect(); let nf = build_frame(&p, &s, cursor, error.as_deref(), color); redraw_replace(&mut stderr, &prev, &nf, width); prev = nf; }
                Key::CtrlW => {
                    while cursor > 0 && input[cursor - 1] == ' ' { cursor -= 1; input.remove(cursor); }
                    while cursor > 0 && input[cursor - 1] != ' ' { cursor -= 1; input.remove(cursor); }
                    let s: String = input.iter().collect(); let nf = build_frame(&p, &s, cursor, error.as_deref(), color); redraw_replace(&mut stderr, &prev, &nf, width); prev = nf;
                }
                Key::Char(c) => {
                    input.insert(cursor, c); cursor += 1;
                    let s: String = input.iter().collect();
                    let new_frame = build_frame(&p, &s, cursor, error.as_deref(), color);
                    redraw_replace(&mut stderr, &prev, &new_frame, width); prev = new_frame;
                }
                Key::Other => {}
            }
        }
    }
}

fn redraw_clear(stderr: &mut std::io::Stderr, prev: &Frame, width: usize) {
    // cursor is at prev caret position. Move to frame start and clear each physical row, leaving cursor at frame start.
    let (total, caret_row, _caret_col) = caret_pos(&prev.plain_lines, prev.caret_line_idx, prev.caret_col_in_line, width);
    let _ = write!(stderr, "\x1b[?25l");
    // mimic inquire: move down to below frame, col1, then go up clearing
    let down = total - caret_row;
    if down > 0 { let _ = write!(stderr, "\x1b[{}B", down); }
    let _ = write!(stderr, "\x1b[1G");
    for _ in 0..total {
        let _ = write!(stderr, "\x1b[1A\x1b[2K");
    }
    let _ = stderr.flush();
}
fn redraw_replace(stderr: &mut std::io::Stderr, prev: &Frame, new_frame: &Frame, width: usize) {
    redraw_clear(stderr, prev, width);
    let _ = write!(stderr, "\x1b[?25l");
    for line in &new_frame.lines { let _ = write!(stderr, "{}\r\n", line); }
    let (total, caret_row, caret_col) = caret_pos(&new_frame.plain_lines, new_frame.caret_line_idx, new_frame.caret_col_in_line, width);
    // special case in inquire when caret_col is 0 of a wrapped row (col 1) - our mapping gives that
    let up = total - caret_row;
    if up > 0 { let _ = write!(stderr, "\x1b[{}A", up); }
    if caret_col == 0 && new_frame.caret_col_in_line > 0 {
        let _ = write!(stderr, "\x1b[1G");
    } else {
        let _ = write!(stderr, "\x1b[{}G", caret_col + 1);
    }
    let _ = write!(stderr, "\x1b[?25h");
    let _ = stderr.flush();
}

fn prompt_or_panic(question: &str, help: Option<&str>, default: bool, location: &str) -> bool {
    let p = Prompt { question, help, default };
    match prompt_confirm_inner(p) {
        Ok(Some(ans)) => ans,
        Ok(None) => default,
        Err(kind) => {
            print_panic(location, &format!("Error while prompting!: {}", kind.as_str()));
            std::process::exit(255);
        }
    }
}

// ---------- generate ci ----------
const LINK_CHECK_BLOCK: &str = "      - name: Prepare HTML for link checking\n        # untitaker/hyperlink supports no site prefixes, move entire site into\n        # a subfolder\n        run: mkdir /tmp/public/ && cp -R public /tmp/public/oranda\n\n      - name: Check HTML for broken internal links\n        uses: untitaker/hyperlink@0.1.29\n        with:\n          args: /tmp/public/\n      \n";

fn ci_template(link_checker: bool, use_latest: bool) -> String {
    let base = include_str!("../src_placeholder_ci_template");
    let _ = base;
    // template loaded from embedded file via a generated constant in main (CI_TEMPLATE)
    let tmpl = crate::CI_TEMPLATE;
    let mut out = tmpl.to_string();
    if use_latest {
        out = out.replace("releases/download/v0.6.1/oranda-installer.sh", "releases/latest/download/oranda-installer.sh");
    }
    if !link_checker {
        out = out.replace(LINK_CHECK_BLOCK, "");
    }
    out
}

pub fn generate_ci(output_path_in: Option<String>, _site_path: Option<String>) -> OrandaResult<()> {
    log_info("Generating a CI deploy workflow for your site...");
    let output_path = output_path_in.unwrap_or_else(|| ".github/workflows/web.yml".to_string());
    let out_path_obj = Path::new(&output_path);
    // existing file override check
    if out_path_obj.exists() {
        let q = format!("There's already a file at {:?}! Do you want to override it?", output_path);
        // Question passed to prompt is the q string without using Debug in renderer: Our Prompt question must be exactly that text (it already includes quotes)
        let p = Prompt { question: &q, help: None, default: false };
        let res = prompt_confirm_inner(p);
        let proceed = match res {
            Ok(Some(false)) => false,
            _ => true,
        };
        if !proceed {
            log_info("Ok, exiting...");
            return Ok(());
        }
        // After proceeding (yes or skipped), try to read the asset (as observed)
        match std::fs::read_to_string(out_path_obj) {
            Ok(_) => {}
            Err(e) => {
                return Err(read_asset_diag(&output_path, &e));
            }
        }
    }
    let link_checker = prompt_or_panic(
        "Do you want to include a tool for checking generated hyperlinks?",
        Some("Read more about the link checker tool: https://github.com/untitaker/hyperlink"),
        true,
        "src/generate.rs:56:14",
    );
    let use_latest = prompt_or_panic(
        "Do you want to always use the latest version of oranda?",
        Some("Using the latest version means you don't have to rerun this command when oranda updates, but it may also break your site if you use a lot of configuration!"),
        false,
        "src/generate.rs:63:10",
    );
    let template = ci_template(link_checker, use_latest);
    let append_gitignore = prompt_or_panic(
        "Would you like to append the default destination directory (`public`) to your .gitignore file?",
        None,
        false,
        "src/generate.rs:77:10",
    );
    if append_gitignore {
        let gi_path = Path::new(".gitignore");
        let existing = if gi_path.exists() {
            match std::fs::read_to_string(gi_path) {
                Ok(s) => s,
                Err(e) => return Err(read_asset_diag(".gitignore", &e)),
            }
        } else { String::new() };
        let new_contents = format!("{}\n# Generated by `oranda generate ci`\npublic/", existing);
        write_new_asset(&new_contents, gi_path)?;
    }
    let _ = &template;
    write_new_asset(&template, out_path_obj)?;
    log_success(&format!("Wrote CI file to {:?}", output_path));
    Ok(())
}
RS

