fn get_global_string(matches: &clap::ArgMatches, name: &str) -> Option<String> {
    // Walk hierarchy deepest last
    fn walk(m: &clap::ArgMatches, name: &str, cur: &mut Option<String>) {
        if let Some(src) = m.value_source(name) {
            if src == clap::parser::ValueSource::CommandLine {
                if let Some(v) = m.get_one::<String>(name) { *cur = Some(v.clone()); }
            }
        }
        if let Some((_, sub)) = m.subcommand() { walk(sub, name, cur); }
    }
    let mut cur = None;
    walk(matches, name, &mut cur);
    // output-format default handling at top level if never commandline
    if cur.is_none() {
        if let Some(v) = matches.get_one::<String>(name) { return Some(v.clone()); }
    }
    cur
}
fn get_global_bool(matches: &clap::ArgMatches, name: &str) -> bool {
    fn walk(m: &clap::ArgMatches, name: &str, cur: &mut bool) {
        if let Some(v) = m.get_one::<bool>(name) { if *v { *cur = true; } }
        if let Some((_, sub)) = m.subcommand() { walk(sub, name, cur); }
