fn platform_suffix() -> &'static str {
    match (std::env::consts::OS, std::env::consts::ARCH) {
        ("linux", "x86_64") => "linux-x64",
        ("linux", "aarch64") => "linux-arm64",
        ("linux", "arm") => "linux-armv7",
        ("macos", "x86_64") => "macos-x64",
        ("macos", "aarch64") => "macos-arm64",
        ("windows", "x86_64") => "windows-x64.exe",
        _ => "linux-x64",
    }
}

fn get_tailwind() -> OrandaResult<String> {
    match Command::new("tailwindcss").arg("--help").status() {
        Ok(s) if s.success() => {
            log_info("Found Tailwind binary on the path!");
            return Ok("tailwindcss".to_string());
        }
        Ok(_) => {}
        Err(_) => {
            log_info("Couldn't find Tailwind binary");
        }
    }
    log_info("Fetching Tailwind binary from GitHub release...");
    let url = format!("https://github.com/tailwindlabs/tailwindcss/releases/latest/download/tailwindcss-{}", platform_suffix());
    let bytes = fetch_bytes(&url).map_err(|fe| fe.to_diag())?;
    let mut path = std::env::temp_dir();
    path.push(if cfg!(windows) { "tailwindcss.exe" } else { "tailwindcss" });
    std::fs::write(&path, &bytes).map_err(|e| Diag::from(e))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o755));
    }
    Ok(path.display().to_string())
}

pub fn generate_css(out_dir: Option<String>) -> OrandaResult<()> {
    let bin = get_tailwind()?;
    log_info("Building oranda CSS using Tailwind...");
    let base = format!("{}/generate-css/../oranda-css", env!("CARGO_MANIFEST_DIR"));
    let config = format!("{}/tailwind.config.js", base);
    let input = format!("{}/css/main.css", base);
    let out_path: PathBuf = if let Some(dir) = out_dir {
        PathBuf::from(dir).join("oranda.css")
    } else {
        PathBuf::from(format!("{}/dist/oranda.css", base))
    };
    let out_s = out_path.display().to_string();
    let output = Command::new(&bin)
        .args(["-c", &config, "-i", &input, "-o", &out_s, "--minify"])
        .stderr(Stdio::inherit())
        .output();
    match output {
        Ok(o) if o.status.success() => {
            log_info(&format!("CSS placed in {}", out_s));
            Ok(())
        }
        _ => {
            print_panic("generate-css/src/lib.rs:53:10", "Tailwind failed to compile CSS!");
            std::process::exit(255);
        }
    }
}
