// ---- old-style (toml 0.5 / mdbook) error translation ----
fn line_col_to_offset(src: &str, line: usize, col: usize) -> usize {
    let mut off = 0usize;
    let mut cur = 1usize;
    for b in src.bytes() {
        if cur >= line { break; }
        off += 1;
        if b == b'\n' { cur += 1; }
    }
    off + col.saturating_sub(1)
}
fn offset_to_line_col(src: &str, offset: usize) -> (usize, usize) {
    let mut line = 1usize; let mut last = 0usize;
    for (i, b) in src.bytes().enumerate() {
        if i >= offset { break; }
        if b == b'\n' { line += 1; last = i + 1; }
    }
    (line, offset - last + 1)
}
fn find_unterminated_string(src: &str) -> Option<(usize, usize)> {
    #[derive(PartialEq)] enum St { Normal, Basic, Literal, MBasic, MLiteral, Comment }
    let bytes: Vec<char> = src.chars().collect();
    // work on byte offsets for line/col mapping using char indices positions in original bytes is approximated by converting char idx to byte via char_indices
    let mut char_to_byte: Vec<usize> = src.char_indices().map(|(i, _)| i).collect(); char_to_byte.push(src.len());
    let mut st = St::Normal;
    let mut i = 0usize;
    let mut start = 0usize; // char idx
    while i < bytes.len() {
        let c = bytes[i];
        match st {
            St::Normal => {
                if c == '#' { st = St::Comment; }
                else if c == '"' {
                    if i + 2 < bytes.len() && bytes[i+1] == '"' && bytes[i+2] == '"' { st = St::MBasic; start = i; i += 2; } else { st = St::Basic; start = i; }
                } else if c == '\'' {
                    if i + 2 < bytes.len() && bytes[i+1] == '\'' && bytes[i+2] == '\'' { st = St::MLiteral; start = i; i += 2; } else { st = St::Literal; start = i; }
                }
            }
            St::Comment => { if c == '\n' { st = St::Normal; } }
            St::Basic => {
                if c == '\\' { i += 1; }
                else if c == '"' { st = St::Normal; }
                else if c == '\n' { return Some(offset_to_line_col(src, char_to_byte[start])); }
            }
            St::Literal => {
                if c == '\'' { st = St::Normal; }
                else if c == '\n' { return Some(offset_to_line_col(src, char_to_byte[start])); }
            }
            St::MBasic => {
                if c == '\\' { i += 1; }
                else if c == '"' && i + 2 < bytes.len() && bytes[i+1] == '"' && bytes[i+2] == '"' { st = St::Normal; i += 2; }
            }
            St::MLiteral => {
                if c == '\'' && i + 2 < bytes.len() && bytes[i+1] == '\'' && bytes[i+2] == '\'' { st = St::Normal; i += 2; }
            }
        }
        i += 1;
    }
    match st { St::Basic | St::Literal | St::MBasic | St::MLiteral => Some(offset_to_line_col(src, char_to_byte[start])), _ => None }
}
fn duplicate_error(src: &str) -> Option<String> {
    use std::collections::{HashMap, HashSet};
    let mut current_table = String::new();
    let mut current_table_line = 1usize;
    let mut seen_headers: HashMap<String, usize> = HashMap::new();
    let mut seen_keys: HashMap<(String, String), usize> = HashMap::new();
    for (idx, raw_line) in src.lines().enumerate() {
        let line_no = idx + 1;
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') { continue; }
        if line.starts_with("[[") { continue; }
        if line.starts_with('[') {
            if let Some(end) = line.find(']') {
                let table = line[1..end].trim().to_string();
                if seen_headers.contains_key(&table) {
                    let segs: Vec<&str> = table.split('.').collect();
                    let last = segs.last().unwrap_or(&" );
                    let for_key = if segs.len() >= 2 { segs[segs.len()-2] } else { &table };
                    // Root single segment case: original says redefinition of table `book` for key `book`
                    return Some(format!("redefinition of table `{}` for key `{}` at line {} column 1", last, if segs.len()>=2 { for_key } else { &table }, line_no));
                }
                seen_headers.insert(table.clone(), line_no);
                current_table = table;
                current_table_line = line_no;
                continue;
            }
        }
        if let Some(eq) = line.find('=') {
            let key_raw = line[..eq].trim().trim_matches(|c| c == '"' || c == '\'');
            if key_raw.is_empty() { continue; }
            let key = key_raw.split('.').last().unwrap_or(key_raw).trim().trim_matches(|c| c=='"' || c=='\'').to_string();
            let full = format!("{}.{}", current_table, key_raw);
            if let Some(first_line) = seen_keys.get(&(current_table.clone(), full.clone())) {
                if current_table.is_empty() {
                    return Some(format!("duplicate key: `{}` at line {} column 1", key, first_line));
                } else {
                    return Some(format!("duplicate key: `{}` for key `{}` at line {} column 1", key, current_table, current_table_line));
                }
            }
            seen_keys.insert((current_table.clone(), full), line_no);
            let _ = seen_headers;
        }
    }
    None
}
pub fn old_toml_error(src: &str, modern: &str) -> String {
    // extract line/col from modern
    let mut mline = 1usize; let mut mcol = 1usize;
    let mut detail = String::new();
    if let Some(first) = modern.lines().next() {
        // "TOML parse error at line 1, column 8"
        let nums: Vec<usize> = first.split(|c: char| !c.is_ascii_digit()).filter(|s| !s.is_empty()).filter_map(|s| s.parse().ok()).collect();
        if nums.len() >= 2 { mline = nums[nums.len()-2]; mcol = nums[nums.len()-1]; }
    }
    for l in modern.lines() { if !l.trim().is_empty() { detail = l.trim().to_string(); } }
    if let Some((l, c)) = find_unterminated_string(src) {
        return format!("unterminated string at line {} column {}", l, c);
    }
    if modern.contains("duplicate key") {
        if let Some(d) = duplicate_error(src) { return d; }
    }
    let offset = line_col_to_offset(src, mline, mcol);
