pub fn old_toml_error(src: &str, modern: &str) -> String {
    // extract line/col from modern
    let mut mline = 1usize; let mut mcol = 1usize;
    let mut detail = String::new();
    if let Some(first) = modern.lines().next() {
        // "TOML parse error at line 1, column 8"
        let nums: Vec<usize> = first.split(|c: char| !c.is_ascii_digit()).filter(|s| !s.is_empty()).filter_map(|s| s.parse().ok()).collect();
        if nums.len() >= 2 { mline = nums[nums.len()-2]; mcol = nums[nums.len()-1]; }
    }
    for l in modern.lines() { if !l.trim().is_empty() { detail = l.trim().to_string(); } }
    if let Some((l, c)) = find_unterminated_string(src) {
        return format!("unterminated string at line {} column {}", l, c);
    }
    if modern.contains("duplicate key") {
        if let Some(d) = duplicate_error(src) { return d; }
    }
    let offset = line_col_to_offset(src, mline, mcol);
    let at_eof = offset >= src.len() || src[offset.min(src.len())..].trim().is_empty();
    if at_eof {
        // Determine unmatched delimiters outside strings/comments (simple scan reusing string state would be complex - scan chars ignoring strings approximately by toggling quotes)
        let mut stack: Vec<char> = Vec::new();
        let mut in_s = false; let mut in_lit = false; let mut in_comment = false; let mut prev = '\0';
        let mut line_start_nonws: Option<char> = None;
        let mut table_header_flags: Vec<bool> = Vec::new();
        for ch in src.chars() {
            if in_comment { if ch == '\n' { in_comment = false; line_start_nonws = None; } prev = ch; continue; }
            if in_s { if prev != '\\' && ch == '"' { in_s = false; } prev = ch; continue; }
            if in_lit { if ch == '\'' { in_lit = false; } prev = ch; continue; }
            match ch {
                '#' => { in_comment = true; }
                '"' => in_s = true,
                '\'' => in_lit = true,
                '\n' => { line_start_nonws = None; }
                '[' => {
                    let is_header = line_start_nonws.is_none();
                    stack.push('['); table_header_flags.push(is_header);
                    if line_start_nonws.is_none() { line_start_nonws = Some(ch); }
                }
                '{' => { stack.push('{'); table_header_flags.push(false); if line_start_nonws.is_none() { line_start_nonws = Some(ch); } }
                ']' => { if stack.last() == Some(&'[') { stack.pop(); table_header_flags.pop(); } if line_start_nonws.is_none() { line_start_nonws = Some(ch); } }
                '}' => { if stack.last() == Some(&'{') { stack.pop(); table_header_flags.pop(); } if line_start_nonws.is_none() { line_start_nonws = Some(ch); } }
                c if !c.is_whitespace() => { if line_start_nonws.is_none() { line_start_nonws = Some(c); } }
                _ => {}
            }
            prev = ch;
        }
        if let Some(top) = stack.last() {
            if *top == '[' && table_header_flags.last().copied().unwrap_or(false) {
                return format!("expected a right bracket, found eof at line {} column {}", mline, mcol);
            }
            if *top == '{' {
                return format!("expected a table key, found eof at line {} column {}", mline, mcol);
            }
        }
        return format!("unexpected eof encountered at line {} column {}", mline, mcol);
    }
    // char at offset
    let ch = src[offset..].chars().next().unwrap_or('\0');
    // line text before offset
    let line_start = src[..offset].rfind('\n').map(|i| i+1).unwrap_or(0);
    let before = &src[line_start..offset];
    let before_trim = before.trim();
    if ch == '=' {
        // distinguish expecting key vs value: if before contains an '=' outside strings (simple contains) then value expected, else key expected
        if before.contains('=') {
            return format!("expected a value, found an equals at line {} column {}", mline, mcol);
        } else {
            return format!("expected a table key, found an equals at line {} column {}", mline, mcol);
        }
    }
    if ch == '}' {
        return format!("expected a value, found a right brace at line {} column {}", mline, mcol);
    }
    if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' || ch == '+' {
        // token
        let token: String = src[offset..].chars().take_while(|c| !c.is_whitespace() && *c != ',' && *c != ']' && *c != '}').collect();
        let is_value_ctx = before_trim.ends_with('=');
        if !is_value_ctx && !before.contains('=') {
            return format!("expected an equals, found an identifier at line {} column {}", mline, mcol);
        }
        if is_value_ctx {
            // datetime / number handling
            let key_part = before.split('=').next().unwrap_or("").trim();
            let key_name = key_part.split('.').last().unwrap_or(key_part).trim().trim_matches(|c| c=='"' || c=='\'');
            let token_core = token.trim_end_matches(|c| c==',' );
            let is_dateish = token_core.len() >= 10 && token_core.chars().take(4).all(|c| c.is_ascii_digit()) && token_core.chars().nth(4) == Some('-');
            if is_dateish {
                return format!("failed to parse datetime for key `{}` at line {} column {}", key_name, mline, mcol);
            }
            let first = token.chars().next().unwrap();
            if first.is_ascii_digit() || ((first=='+'||first=='-') && token.chars().nth(1).map(|c| c.is_ascii_digit()).unwrap_or(false)) {
                // leading zero case: error at second digit
                let digits: String = token.chars().skip(if first=='+'||first=='-' {1} else {0}).take_while(|c| c.is_ascii_digit()).collect();
                let mut col = mcol;
                if digits.len() > 1 && digits.starts_with('0') { col = mcol + 1; }
                return format!("invalid number at line {} column {}", mline, col);
            }
            return format!("invalid TOML value, did you mean to use a quoted string? at line {} column {}", mline, mcol);
        }
    }
    // fallback use modern detail with old at-line format
    if !detail.is_empty() {
        return format!("{} at line {} column {}", detail, mline, mcol);
    }
    format!("unexpected eof encountered at line {} column {}", mline, mcol)
}
