        if !Path::new(&md_candidate).is_file() && Path::new(&yml_candidate).is_file() {
            if let Ok(yml) = std::fs::read_to_string(&yml_candidate) {
                let mut body = String::from("<ul>\\n");
                for line in yml.lines() {
