        if let Some(repo) = cfg.repository() { f.push_str(&format!("<a href=\"{}\">Repository</a>\n", html_escape(&repo))); }
        f
    };
    format!("<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>{}</title>\n{}<link rel=\"stylesheet\" href=\"{}\">\n<link rel=\"icon\" href=\"{}\">\n</head>\n<body class=\"{}\">\n<header>{}<h1>{}</h1>\n{}</header>\n<main>\n{}</main>\n<footer>{}</footer>\n</body>\n</html>\n", html_escape(title), head_extra, css_href, build_url_path(cfg.path_prefix.as_deref(), "favicon.ico"), theme_class, logo_html, html_escape(&name), nav, body_html, footer)
}
