    nav_items.push(("Home".to_string(), build_url_path(cfg.path_prefix.as_deref(), "")));
    for (label, _path) in &cfg.additional_pages {
        nav_items.push((label.clone(), build_url_path(cfg.path_prefix.as_deref(), &format!("{}/", slugify(label)))));
    }
    if artifacts_enabled(cfg) { nav_items.push(("Install".to_string(), build_url_path(cfg.path_prefix.as_deref(), "artifacts/"))); }
    if cfg.changelog_enabled() { nav_items.push(("Changelog".to_string(), build_url_path(cfg.path_prefix.as_deref(), "changelog/"))); }
    if cfg.funding_enabled() && (Path::new(&cfg.funding_md_candidate()).is_file() || Path::new(&cfg.funding_yml_candidate()).is_file()) {
        nav_items.push(("Funding".to_string(), build_url_path(cfg.path_prefix.as_deref(), "funding/")));
    }
    if cfg.mdbook_enabled() {
        // only if a book is discoverable (ignore errors here to avoid failing layout)
        if let Ok(Some(_)) = crate::mdbook::find_mdbook(cfg) {
            nav_items.push(("Docs".to_string(), build_url_path(cfg.path_prefix.as_deref(), "docs/")));
        }
    }
    let mut nav = String::from("<nav>\n");
    for (label, href) in &nav_items {
        nav.push_str(&format!("<a href=\"{}\">{}</a>\n", html_escape(href), html_escape(label)));
    }
    nav.push_str("</nav>\n");
    let logo_html = if let Some(logo) = &cfg.styles().logo {
        let src = if logo.starts_with("http://") || logo.starts_with("https://") { logo.clone() } else {
            let fname = std::path::Path::new(logo).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| logo.clone());
            build_url_path(cfg.path_prefix.as_deref(), &fname)
        };
        format!("<img src=\"{}\" alt=\"{}\">\n", html_escape(&src), html_escape(&name))
    } else { String::new() };
    let footer = {
        let mut f = String::new();
        if let Some(lic) = cfg.license() { f.push_str(&format!("<p>{}</p>\n", html_escape(&lic))); }
        if let Some(repo) = cfg.repository() { f.push_str(&format!("<a href=\"{}\">Repository</a>\n", html_escape(&repo))); }
        f
    };
    format!("<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>{}</title>\n{}<link rel=\"stylesheet\" href=\"{}\">\n<link rel=\"icon\" href=\"{}\">\n</head>\n<body class=\"{}\">\n<header>{}<h1>{}</h1>\n{}</header>\n<main>\n{}</main>\n<footer>{}</footer>\n</body>\n</html>\n", html_escape(title), head_extra, css_href, build_url_path(cfg.path_prefix.as_deref(), "favicon.ico"), theme_class, logo_html, html_escape(&name), nav, body_html, footer)
}
